
  window.SNLE_POSTERS=[{"page":1,"id":"poster-001","slug":"abcde-first-look-action-guide","title":"ABCDE First-Look & Action Guide","arabic":"دليل ABCDE للتقييم والتدخل الأولي","group":"priority","groupLabel":"Priority & nursing process","toolIds":[1],"utilityKeys":["ABCDE"],"canonical":true,"selectionNote":"Upgraded poster selected","asset":"posters/poster-001-abcde-first-look-action-guide.webp","questionIds":["Q0001","Q0002","Q0003","Q0004","Q0005","Q0006","Q0007","Q0008","Q0009","Q0010"],"questionCount":10,"meanHyp":86,"domains":["Nursing Fundamentals"],"job":"Primary survey of an acutely unwell patient when a pulse/circulation state has not established cardiac arrest.","boundary":"Use ABCDE to find the first life threat. If pulseless arrest is established, CAB takes over. If the question is broader multi-system deterioration/first action, use Deterioration Coach.","handoffs":[{"tool":"CAB","trigger":"Pulseless arrest / CPR sequence"},{"tool":"Deterioration & First-Action Coach","trigger":"Broader deterioration with several competing clues"}],"pearl":"Treat the earliest unresolved life threat, then reassess from A again.","trap":"Do not use ABCDE Priority Framework as a rigid slogan; compare the patient's actual severity, timing, safety, scope, and response.","dataUri":"/assets/media/d0b2e07af5ff27d8.webp"},{"page":2,"id":"poster-002","slug":"abg-stepwise-interpreter","title":"ABG Stepwise Interpreter","arabic":"المفسر المتدرج لغازات الدم الشرياني","group":"labs","groupLabel":"Labs & monitoring","toolIds":[38],"utilityKeys":["ABG Stepwise Interpreter"],"canonical":true,"selectionNote":"Upgraded poster selected","asset":"posters/poster-002-abg-stepwise-interpreter.webp","questionIds":["Q0371","Q0372","Q0373","Q0374","Q0375","Q0376","Q0377","Q0378","Q0379","Q0380"],"questionCount":10,"meanHyp":90,"domains":["Adult Nursing"],"job":"Interpret acid-base pattern systematically: pH, PaCO₂, HCO₃⁻, compensation, oxygenation, clinical context.","boundary":"ABG interpretation identifies the pattern. Oxygenation Lab owns device/oxygen/suctioning interventions.","handoffs":[{"tool":"Oxygenation, Oxygen Therapy & Suctioning Decision Lab","trigger":"The task is oxygen-device choice or suctioning rather than ABG classification"}],"pearl":"Normal pH can hide two abnormal processes pulling in opposite directions.","trap":"Do not use ABG Stepwise Interpreter as a rigid slogan; compare the patient's actual severity, timing, safety, scope, and response.","dataUri":"/assets/media/777d7c6a3abb15df.webp"},{"page":3,"id":"poster-003","slug":"adpie-framework","title":"ADPIE Framework","arabic":"إطار العملية التمريضية ADPIE","group":"priority","groupLabel":"Priority & nursing process","toolIds":[11],"utilityKeys":["ADPIE"],"canonical":true,"selectionNote":"Upgraded poster selected","asset":"posters/poster-003-adpie-framework.webp","questionIds":["Q0101","Q0102","Q0103","Q0104","Q0105","Q0106","Q0107","Q0108","Q0109","Q0110"],"questionCount":10,"meanHyp":77,"domains":["Nursing Fundamentals"],"job":"Identify or sequence the nursing-process phase: Assessment, Diagnosis, Planning, Implementation, Evaluation.","boundary":"ADPIE owns nursing-process sequencing. Assess Before Acting owns a clinical timing decision, not the whole nursing process.","handoffs":[{"tool":"Assess Before Acting","trigger":"The task is whether to gather a focused finding before an intervention"}],"pearl":"ADPIE is cyclic: evaluation frequently sends the nurse back to assessment and planning.","trap":"Do not use ADPIE Nursing Process as a rigid slogan; compare the patient's actual severity, timing, safety, scope, and response.","dataUri":"/assets/media/7d34d82b026d5917.webp"},{"page":4,"id":"poster-004","slug":"apgar-newborn-assessment-guide","title":"APGAR Newborn Assessment Guide","arabic":"دليل تقييم حديث الولادة APGAR","group":"maternal","groupLabel":"Maternal & pediatrics","toolIds":[34],"utilityKeys":["APGAR"],"canonical":true,"selectionNote":"Upgraded poster selected","asset":"posters/poster-004-apgar-newborn-assessment-guide.webp","questionIds":["Q0331","Q0332","Q0333","Q0334","Q0335","Q0336","Q0337","Q0338","Q0339","Q0340"],"questionCount":10,"meanHyp":88,"domains":["Maternal-Child Nursing"],"job":"Score newborn adaptation at the specified post-birth time using appearance, pulse, grimace, activity and respiration.","boundary":"APGAR is a newborn adaptation score, not a general neonatal emergency-management framework.","handoffs":[{"tool":"Pediatric & Newborn Rapid Pattern Atlas","trigger":"Need broader newborn/pediatric pattern recognition or intervention"}],"pearl":"NRP determines action; APGAR documents condition and response.","trap":"Do not use APGAR Newborn Assessment as a rigid slogan; compare the patient's actual severity, timing, safety, scope, and response.","dataUri":"/assets/media/19c766cd1eaedb54.webp"},{"page":5,"id":"poster-005","slug":"avpu-clinical-decision-guide","title":"AVPU Clinical Decision Guide","arabic":"دليل القرار السريري AVPU","group":"assessment","groupLabel":"Assessment & emergency","toolIds":[30],"utilityKeys":["AVPU"],"canonical":true,"selectionNote":"Upgraded poster selected","asset":"posters/poster-005-avpu-clinical-decision-guide.webp","questionIds":["Q0291","Q0292","Q0293","Q0294","Q0295","Q0296","Q0297","Q0298","Q0299","Q0300"],"questionCount":10,"meanHyp":82,"domains":["Nursing Fundamentals"],"job":"Very rapid consciousness classification: Alert, Voice, Pain, Unresponsive.","boundary":"AVPU is a fast first impression, not a substitute for detailed GCS trending when the question asks for a score.","handoffs":[{"tool":"Glasgow Coma Scale","trigger":"Need detailed neurologic scoring/trending"}],"pearl":"Use only the stimulus necessary to establish the highest response; U does not mean cardiac arrest.","trap":"Do not use AVPU / ACVPU as a rigid slogan; compare the patient's actual severity, timing, safety, scope, and response.","dataUri":"/assets/media/b862f9f08e3e4f5a.webp"},{"page":6,"id":"poster-006","slug":"actual-before-potential","title":"Actual Before Potential","arabic":"المشكلة الفعلية قبل المحتملة","group":"priority","groupLabel":"Priority & nursing process","toolIds":[7],"utilityKeys":["Actual Before Potential"],"canonical":true,"selectionNote":"Upgraded poster selected","asset":"posters/poster-006-actual-before-potential.webp","questionIds":["Q0061","Q0062","Q0063","Q0064","Q0065","Q0066","Q0067","Q0068","Q0069","Q0070"],"questionCount":10,"meanHyp":78,"domains":["Nursing Fundamentals"],"job":"When severity is comparable, prioritize an existing current problem over a future risk.","boundary":"Potential threats can outrank actual problems if the potential harm is imminent/catastrophic; use this only as a comparable-severity tie-breaker.","handoffs":[{"tool":"Safety First","trigger":"The potential threat is immediate serious harm"}],"pearl":"Compare urgency and harm, not just the labels actual versus potential.","trap":"Do not use Actual Before Potential as a rigid slogan; compare the patient's actual severity, timing, safety, scope, and response.","dataUri":"/assets/media/2eec6d676d908c32.webp"},{"page":7,"id":"poster-007","slug":"acute-before-chronic","title":"Acute Before Chronic","arabic":"الحاد قبل المزمن","group":"priority","groupLabel":"Priority & nursing process","toolIds":[6],"utilityKeys":["Acute Before Chronic"],"canonical":true,"selectionNote":"Upgraded poster selected","asset":"posters/poster-007-acute-before-chronic.webp","questionIds":["Q0051","Q0052","Q0053","Q0054","Q0055","Q0056","Q0057","Q0058","Q0059","Q0060"],"questionCount":10,"meanHyp":76,"domains":["Nursing Fundamentals"],"job":"When stability is comparable, prioritize the new acute problem over an unchanged chronic baseline.","boundary":"Never use acute-before-chronic to outrank instability. Newness matters only after safety/stability is comparable.","handoffs":[{"tool":"Unstable Before Stable","trigger":"One option/patient is unstable"},{"tool":"Unexpected Before Expected","trigger":"The question is expected-vs-abnormal finding rather than chronology"}],"pearl":"A severe acute-on-chronic deterioration outranks a trivial new problem.","trap":"Do not use Acute Before Chronic as a rigid slogan; compare the patient's actual severity, timing, safety, scope, and response.","dataUri":"/assets/media/087109f5932dcb42.webp"},{"page":8,"id":"poster-008","slug":"assess-before-acting","title":"Assess Before Acting","arabic":"قيّم قبل أن تتدخل","group":"priority","groupLabel":"Priority & nursing process","toolIds":[9],"utilityKeys":["Assess Before Acting"],"canonical":true,"selectionNote":"Upgraded poster selected","asset":"posters/poster-008-assess-before-acting.webp","questionIds":["Q0081","Q0082","Q0083","Q0084","Q0085","Q0086","Q0087","Q0088","Q0089","Q0090"],"questionCount":10,"meanHyp":78,"domains":["Nursing Fundamentals"],"job":"Perform the focused assessment that is needed to choose the safe intervention when delay is acceptable.","boundary":"Assessment-first is conditional, not absolute. If the stem already establishes a time-critical threat, act first.","handoffs":[{"tool":"Emergency Exception","trigger":"A brief assessment would dangerously delay treatment"},{"tool":"ADPIE","trigger":"The question asks which nursing-process phase comes next"}],"pearl":"If you do not know enough and time permits, assess; if the life threat is already known, act.","trap":"Do not use Assess Before Acting as a rigid slogan; compare the patient's actual severity, timing, safety, scope, and response.","dataUri":"/assets/media/07664ca97477ce77.webp"},{"page":9,"id":"poster-009","slug":"be-fast-stroke-recognition","title":"BE-FAST Stroke Recognition","arabic":"التعرف السريع على السكتة BE-FAST","group":"assessment","groupLabel":"Assessment & emergency","toolIds":[28],"utilityKeys":["BE-FAST"],"canonical":true,"selectionNote":"Upgraded poster selected","asset":"posters/poster-009-be-fast-stroke-recognition.webp","questionIds":["Q0271","Q0272","Q0273","Q0274","Q0275","Q0276","Q0277","Q0278","Q0279","Q0280"],"questionCount":10,"meanHyp":99,"domains":["Adult Nursing"],"job":"Rapidly screen for stroke warning signs and trigger urgent stroke response.","boundary":"BE-FAST is a stroke screen, not a general consciousness score.","handoffs":[{"tool":"Glasgow Coma Scale","trigger":"Need detailed neurologic consciousness scoring"},{"tool":"AVPU","trigger":"Need very rapid consciousness categorization"}],"pearl":"One sudden focal warning sign is enough to activate urgent stroke evaluation; record last-known-well.","trap":"Do not use BE-FAST Stroke Recognition as a rigid slogan; compare the patient's actual severity, timing, safety, scope, and response.","dataUri":"/assets/media/0cb1c99a71bcb1e6.webp"},{"page":10,"id":"poster-010","slug":"blood-blood-products-safety","title":"Blood & Blood Products Safety","arabic":"سلامة الدم ومشتقاته","group":"medication","groupLabel":"Medication & infusion","toolIds":[48],"utilityKeys":["Blood & Blood Products Safety Lab"],"canonical":true,"selectionNote":"Upgraded poster selected","asset":"posters/poster-010-blood-blood-products-safety.webp","questionIds":["Q0471","Q0472","Q0473","Q0474","Q0475","Q0476","Q0477","Q0478","Q0479","Q0480"],"questionCount":10,"meanHyp":82,"domains":["Adult Nursing"],"job":"Safely verify, start, monitor and respond to blood-product administration and transfusion reactions.","boundary":"Blood Product Lab owns transfusion workflow/reactions. Identifier and medication tools cover only parts of that workflow.","handoffs":[{"tool":"Two Patient Identifiers","trigger":"The only issue is identity verification before administration"},{"tool":"High-Alert & Special Medication Considerations Lab","trigger":"The question is a high-alert medication rather than a blood product"}],"pearl":"Choose the component for the physiologic deficit, and stop the transfusion first if an acute reaction is suspected.","trap":"Do not use Blood & Blood Products as a rigid slogan; compare the patient's actual severity, timing, safety, scope, and response.","dataUri":"/assets/media/6ee8626a2b5e12ef.webp"},{"page":11,"id":"poster-011","slug":"cab-first-look-action-guide","title":"CAB First-Look & Action Guide","arabic":"دليل CAB للإنعاش القلبي","group":"assessment","groupLabel":"Assessment & emergency","toolIds":[2],"utilityKeys":["CAB"],"canonical":true,"selectionNote":"Upgraded poster selected","asset":"posters/poster-011-cab-first-look-action-guide.webp","questionIds":["Q0011","Q0012","Q0013","Q0014","Q0015","Q0016","Q0017","Q0018","Q0019","Q0020"],"questionCount":10,"meanHyp":99,"domains":["Adult Nursing"],"job":"Cardiac-arrest sequence when pulselessness/arrest makes compressions the first action.","boundary":"CAB is not a generic unstable-patient tool. It owns confirmed/suspected cardiac arrest where circulation/compressions lead.","handoffs":[{"tool":"ABCDE","trigger":"Unstable patient with a pulse or no established arrest"}],"pearl":"No definite pulse within 10 seconds in an unresponsive, nonnormally breathing adult means treat as cardiac arrest.","trap":"Do not use C-A-B / Adult Cardiac-Arrest CPR as a rigid slogan; compare the patient's actual severity, timing, safety, scope, and response.","dataUri":"/assets/media/699d061465a05301.webp"},{"page":12,"id":"poster-012","slug":"cus-clinical-decision-guide","title":"CUS Clinical Decision Guide","arabic":"دليل التصعيد الآمن CUS","group":"communication","groupLabel":"Communication & leadership","toolIds":[17],"utilityKeys":["CUS"],"canonical":true,"selectionNote":"Upgraded poster selected","asset":"posters/poster-012-cus-clinical-decision-guide.webp","questionIds":["Q0161","Q0162","Q0163","Q0164","Q0165","Q0166","Q0167","Q0168","Q0169","Q0170"],"questionCount":10,"meanHyp":76,"domains":["Nursing Management and Leadership"],"job":"Use graded assertive language to escalate a safety concern: Concerned, Uncomfortable, Safety issue.","boundary":"CUS is the language of escalation, not the organizational ladder. If the concern stays unresolved, move to Chain of Command.","handoffs":[{"tool":"Chain of Command","trigger":"Concern remains unresolved after direct assertion"},{"tool":"SBAR / ISBAR","trigger":"Need structured clinical report rather than graded assertion"}],"pearl":"Firm on safety, respectful toward people.","trap":"Do not use CUS as a rigid slogan; compare the patient's actual severity, timing, safety, scope, and response.","dataUri":"/assets/media/86e67e089c2a261b.webp"},{"page":13,"id":"poster-013","slug":"closed-loop-communication","title":"Closed-Loop Communication","arabic":"التواصل ذو الحلقة المغلقة","group":"communication","groupLabel":"Communication & leadership","toolIds":[19],"utilityKeys":["Closed-Loop Communication"],"canonical":true,"selectionNote":"Upgraded poster selected","asset":"posters/poster-013-closed-loop-communication.webp","questionIds":["Q0181","Q0182","Q0183","Q0184","Q0185","Q0186","Q0187","Q0188","Q0189","Q0190"],"questionCount":10,"meanHyp":76,"domains":["Nursing Management and Leadership"],"job":"Send an urgent team message, have the receiver acknowledge/repeat it, then confirm completion.","boundary":"Closed-loop is message confirmation in active team care, not a full report or handoff structure.","handoffs":[{"tool":"SBAR / ISBAR","trigger":"Need structured clinical report"},{"tool":"I-PASS","trigger":"Need transfer-of-care handoff"}],"pearl":"Heard is not the same as understood until the sender verifies the check-back.","trap":"Do not use Closed-Loop Communication as a rigid slogan; compare the patient's actual severity, timing, safety, scope, and response.","dataUri":"/assets/media/0eacf0bb057182e3.webp"},{"page":14,"id":"poster-014","slug":"core-laboratory-pattern-atlas","title":"Core Laboratory Pattern Atlas","arabic":"أطلس أنماط التحاليل الأساسية","group":"labs","groupLabel":"Labs & monitoring","toolIds":[52],"utilityKeys":["Core Laboratory Pattern Atlas"],"canonical":true,"selectionNote":"Upgraded poster selected","asset":"posters/poster-014-core-laboratory-pattern-atlas.webp","questionIds":["Q0511","Q0512","Q0513","Q0514","Q0515","Q0516","Q0517","Q0518","Q0519","Q0520"],"questionCount":10,"meanHyp":82,"domains":["Nursing Fundamentals"],"job":"Interpret routine lab families by purpose, range/trend, high-vs-low meaning, patient context and first nursing follow-up.","boundary":"Core Lab owns routine pattern recognition. Leave it when the question becomes immediate critical danger, acute glycemia management, or medication-specific safety.","handoffs":[{"tool":"Critical Lab & Electrolyte Prioritizer","trigger":"Critical value/symptoms/ECG make urgency the task"},{"tool":"Glycemia & Diabetes Acute Safety Lab","trigger":"Hypoglycemia/DKA/HHS/insulin safety drives the case"},{"tool":"High-Alert & Special Medication Considerations Lab","trigger":"Anticoagulant/electrolyte replacement medication gate drives the answer"}],"pearl":"Interpret laboratory patterns with the patient, trend, local reference interval, and clinical context rather than a single number.","trap":"Do not diagnose from a single laboratory number; use the local reference interval, trend, symptoms, and patient context.","dataUri":"/assets/media/87cc150fcf30347e.webp"},{"page":15,"id":"poster-015","slug":"critical-lab-electrolyte-prioritizer","title":"Critical Lab & Electrolyte Prioritizer","arabic":"ترتيب أولوية التحاليل الحرجة والكهارل","group":"labs","groupLabel":"Labs & monitoring","toolIds":[55],"utilityKeys":["Critical Lab & Electrolyte Prioritizer"],"canonical":true,"selectionNote":"Upgraded poster selected","asset":"posters/poster-015-critical-lab-electrolyte-prioritizer.webp","questionIds":["Q0541","Q0542","Q0543","Q0544","Q0545","Q0546","Q0547","Q0548","Q0549","Q0550"],"questionCount":10,"meanHyp":76,"domains":["Nursing Fundamentals"],"job":"Rank immediate danger from critical labs/electrolytes using symptoms, ECG, trend and consequences.","boundary":"Critical Lab owns urgency/what threatens now. Core Lab owns routine panel patterns/trends. ECG Reader owns rhythm identification.","handoffs":[{"tool":"Core Laboratory Pattern Atlas","trigger":"Routine panel/trend interpretation without immediate critical threat"},{"tool":"ECG & Lethal Rhythm Rapid Reader","trigger":"The rhythm itself is the classification task"}],"pearl":"A critical result is patient plus number plus context: assess immediate threat, verify when appropriate, communicate, treat, and reassess.","trap":"Critical-value policies are local; assess the patient and urgency before applying an automatic action.","dataUri":"/assets/media/693233d0f41b32fd.webp"},{"page":16,"id":"poster-016","slug":"deterioration-first-action-coach","title":"Deterioration & First-Action Coach","arabic":"مدرب التدهور وأول تدخل","group":"assessment","groupLabel":"Assessment & emergency","toolIds":[53],"utilityKeys":["Deterioration & First-Action Coach"],"canonical":true,"selectionNote":"Upgraded poster selected","asset":"posters/poster-016-deterioration-first-action-coach.webp","questionIds":["Q0521","Q0522","Q0523","Q0524","Q0525","Q0526","Q0527","Q0528","Q0529","Q0530"],"questionCount":10,"meanHyp":94,"domains":["Adult Nursing"],"job":"Integrate multi-system deterioration clues and choose the safest first action/escalation.","boundary":"Deterioration Coach owns the whole unstable-patient branch when several clues compete. Use focused tools when the question is specifically a primary survey, oxygen device, rhythm, or critical lab.","handoffs":[{"tool":"ABCDE","trigger":"The task is explicitly the primary survey sequence"},{"tool":"Oxygenation, Oxygen Therapy & Suctioning Decision Lab","trigger":"The stem is specifically oxygen/suctioning"},{"tool":"ECG & Lethal Rhythm Rapid Reader","trigger":"The rhythm is the main classification/first-action problem"}],"pearl":"Recognize deterioration from trends and clinical concern, stabilize ABCDE threats, escalate, and reassess according to acuity.","trap":"Do not wait for a memorized cutoff when the patient is clearly deteriorating; clinical concern and trends matter.","dataUri":"/assets/media/dcaa979a39f701bc.webp"},{"page":17,"id":"poster-017","slug":"difference-contrast-decision-lab","title":"Difference / Contrast Decision Lab","arabic":"مختبر الفروق والمقارنة","group":"priority","groupLabel":"Priority & nursing process","toolIds":[54],"utilityKeys":["Difference / Contrast Decision Lab"],"canonical":true,"selectionNote":"Upgraded poster selected","asset":"posters/poster-017-difference-contrast-decision-lab.webp","questionIds":["Q0531","Q0532","Q0533","Q0534","Q0535","Q0536","Q0537","Q0538","Q0539","Q0540"],"questionCount":10,"meanHyp":79,"domains":["Nursing Fundamentals"],"job":"Meta-tool for distinguishing nearest competing concepts by the single decisive difference and safety consequence.","boundary":"This tool owns “which of these similar things is it?” It should not replace the specialist tool when the question asks what to do after the distinction is made.","handoffs":[{"tool":"Critical Lab & Electrolyte Prioritizer","trigger":"After distinguishing a lab pattern, urgency/action is the task"},{"tool":"Infection Control Selector","trigger":"After distinguishing isolation categories, disease-specific management is the task"},{"tool":"IV Therapy & Fluid Balance Lab","trigger":"After distinguishing IV complications/fluids, therapy response is the task"}],"pearl":"Use discriminating findings to separate similar conditions, but switch immediately to emergency stabilization when instability appears.","trap":"Do not let a comparison mnemonic delay ABCDE stabilization or overinterpret one shared symptom.","dataUri":"/assets/media/52765bcc114d9201.webp"},{"page":18,"id":"poster-018","slug":"ecg-lethal-rhythm-rapid-reader","title":"ECG & Lethal Rhythm Rapid Reader","arabic":"القارئ السريع لتخطيط القلب والنظم المميتة","group":"labs","groupLabel":"Labs & monitoring","toolIds":[40],"utilityKeys":["ECG & Lethal Rhythm Rapid Reader"],"canonical":true,"selectionNote":"Upgraded poster selected","asset":"posters/poster-018-ecg-lethal-rhythm-rapid-reader.webp","questionIds":["Q0391","Q0392","Q0393","Q0394","Q0395","Q0396","Q0397","Q0398","Q0399","Q0400"],"questionCount":10,"meanHyp":95,"domains":["Adult Nursing"],"job":"Recognize rhythm/stability patterns and identify lethal-rhythm first-action pathways.","boundary":"ECG Reader owns the rhythm. Critical Lab owns lab-triggered urgency; Deterioration owns broader instability when rhythm is only one clue.","handoffs":[{"tool":"Critical Lab & Electrolyte Prioritizer","trigger":"An electrolyte/critical lab abnormality drives the ECG risk"},{"tool":"Deterioration & First-Action Coach","trigger":"Rhythm is one part of broader deterioration"}],"pearl":"Always ask: pulse or no pulse, and is the patient stable or unstable?","trap":"Do not use ECG & Lethal Rhythm Rapid Reader as a rigid slogan; compare the patient's actual severity, timing, safety, scope, and response.","dataUri":"/assets/media/896c17285752280a.webp"},{"page":19,"id":"poster-019","slug":"emergency-exception","title":"Emergency Exception","arabic":"استثناء الطوارئ","group":"priority","groupLabel":"Priority & nursing process","toolIds":[10],"utilityKeys":["Emergency Exception"],"canonical":true,"selectionNote":"Upgraded poster selected","asset":"posters/poster-019-emergency-exception.webp","questionIds":["Q0091","Q0092","Q0093","Q0094","Q0095","Q0096","Q0097","Q0098","Q0099","Q0100"],"questionCount":10,"meanHyp":85,"domains":["Nursing Fundamentals"],"job":"Override routine assess-first sequencing when delay threatens life, limb, or function.","boundary":"Use only when the emergency is already established. It does not mean skipping rapid safety assessment in every unstable case.","handoffs":[{"tool":"ABCDE","trigger":"Rapid primary survey is still needed"},{"tool":"CAB","trigger":"Pulseless arrest is established"}],"pearl":"Known immediate threat: recognize, act, call for help, reassess - do not delay for a routine full assessment.","trap":"Do not use Emergency Exception as a rigid slogan; compare the patient's actual severity, timing, safety, scope, and response.","dataUri":"/assets/media/07124b7de1205b96.webp"},{"page":20,"id":"poster-020","slug":"fall-prevention-post-fall-response","title":"Fall Prevention & Post-Fall Response","arabic":"الوقاية من السقوط والاستجابة بعده","group":"safety","groupLabel":"Safety & infection","toolIds":[64],"utilityKeys":["Fall Prevention & Post-Fall Response Lab"],"canonical":true,"selectionNote":"Upgraded poster selected","asset":"posters/poster-020-fall-prevention-post-fall-response.webp","questionIds":["Q0631","Q0632","Q0633","Q0634","Q0635","Q0636","Q0637","Q0638","Q0639","Q0640"],"questionCount":10,"meanHyp":74,"domains":["Nursing Fundamentals"],"job":"Assess dynamic fall risk, tailor prevention, respond safely after a fall and revise the plan.","boundary":"Fall Lab owns prevention/post-fall patient care. Least Restrictive applies if restraint choices arise; Safety Event Lab applies when reporting/system-event analysis is the task.","handoffs":[{"tool":"Least Restrictive","trigger":"The specific question is restraint choice"},{"tool":"Patient Safety Event & Sentinel Event Decision Lab","trigger":"The task is event classification/reporting/RCA after the fall"}],"pearl":"Use structured risk assessment as an aid, not a prediction guarantee; target modifiable risk factors and assess injury before moving a fallen patient.","trap":"A risk score is not a guarantee; individualized prevention and immediate post-fall patient assessment come first.","dataUri":"/assets/media/d467a83aa00eccab.webp"},{"page":21,"id":"poster-021","slug":"fetal-monitoring-obstetric-emergency","title":"Fetal Monitoring & Obstetric Emergency","arabic":"مراقبة الجنين وطوارئ الولادة","group":"maternal","groupLabel":"Maternal & pediatrics","toolIds":[63,70,71],"utilityKeys":["Fetal Monitoring & Obstetric Emergency Lab"],"canonical":true,"selectionNote":"Upgraded poster selected","asset":"posters/poster-021-fetal-monitoring-obstetric-emergency.webp","questionIds":["Q0621","Q0622","Q0623","Q0624","Q0625","Q0626","Q0627","Q0628","Q0629","Q0630","Q0691","Q0692","Q0693","Q0694","Q0695","Q0696","Q0697","Q0698","Q0699","Q0700","Q0701","Q0702","Q0703","Q0704","Q0705","Q0706","Q0707","Q0708","Q0709","Q0710"],"questionCount":30,"meanHyp":90,"domains":["Maternal-Child Nursing"],"job":"Interpret fetal monitoring and obstetric emergencies with assessment, interventions, escalation and reassessment.","boundary":"This advanced lab owns management. VEAL–CHOP and Four Ts are quick recognition mnemonics only.","handoffs":[{"tool":"VEAL–CHOP","trigger":"The question asks only deceleration-to-cause recognition"},{"tool":"Four Ts of PPH","trigger":"The question asks only PPH cause category"}],"pearl":"Interpret FHR category accurately, use cause-directed intrauterine resuscitation, and do not give routine maternal oxygen when the mother is not hypoxic.","trap":"Do not give routine maternal oxygen for fetal resuscitation when the mother is not hypoxic; do not omit recurrent variable decelerations from Category III when variability is absent.","dataUri":"/assets/media/b4270b334137dc6f.webp"},{"page":22,"id":"poster-022","slug":"five-rights-of-delegation","title":"Five Rights of Delegation","arabic":"الحقوق الخمسة للتفويض","group":"communication","groupLabel":"Communication & leadership","toolIds":[14],"utilityKeys":["Five Rights of Delegation"],"canonical":true,"selectionNote":"Upgraded poster selected","asset":"posters/poster-022-five-rights-of-delegation.webp","questionIds":["Q0131","Q0132","Q0133","Q0134","Q0135","Q0136","Q0137","Q0138","Q0139","Q0140"],"questionCount":10,"meanHyp":75,"domains":["Nursing Management and Leadership"],"job":"Decide whether and how a task can be delegated to another team member for this patient and situation.","boundary":"Delegation assumes someone else may perform the task; scope/competency must still be valid. Leadership Matrix owns broader assignment/prioritization/staffing decisions.","handoffs":[{"tool":"Scope-of-Practice Filter","trigger":"The core question is whether the role is authorized/competent"},{"tool":"Leadership & Management Decision Matrix","trigger":"The case is broader staffing/assignment/management"}],"pearl":"Can they do it comes before should I delegate it now.","trap":"Do not use Five Rights of Delegation as a rigid slogan; compare the patient's actual severity, timing, safety, scope, and response.","dataUri":"/assets/media/6e407aa22528d6e7.webp"},{"page":23,"id":"poster-023","slug":"four-ts-of-postpartum-hemorrhage","title":"Four Ts of Postpartum Hemorrhage","arabic":"الأسباب الأربعة لنزف ما بعد الولادة","group":"maternal","groupLabel":"Maternal & pediatrics","toolIds":[36,72,130],"utilityKeys":["Four Ts of PPH"],"canonical":true,"selectionNote":"Upgraded poster selected","asset":"posters/poster-023-four-ts-of-postpartum-hemorrhage.webp","questionIds":["Q0351","Q0352","Q0353","Q0354","Q0355","Q0356","Q0357","Q0358","Q0359","Q0360","Q0711","Q0712","Q0713","Q0714","Q0715","Q0716","Q0717","Q0718","Q0719","Q0720","Q1281","Q1282","Q1283","Q1284","Q1285","Q1286","Q1287","Q1288","Q1289","Q1290"],"questionCount":30,"meanHyp":95,"domains":["Maternal-Child Nursing"],"job":"Organize causes of postpartum hemorrhage: Tone, Trauma, Tissue, Thrombin.","boundary":"Four Ts owns PPH cause differentiation. The Fetal/Obstetric Lab owns the broader emergency pathway and fetal monitoring.","handoffs":[{"tool":"Fetal Monitoring & Obstetric Emergency Lab","trigger":"The case is broader obstetric emergency or fetal-monitoring management"}],"pearl":"Treat hemorrhage and find the cause in parallel.","trap":"Do not use Four Ts of Postpartum Hemorrhage as a rigid slogan; compare the patient's actual severity, timing, safety, scope, and response.","dataUri":"/assets/media/2c03a5bf7c3093c3.webp"},{"page":24,"id":"poster-024","slug":"glasgow-coma-scale","title":"Glasgow Coma Scale","arabic":"مقياس غلاسكو للغيبوبة","group":"assessment","groupLabel":"Assessment & emergency","toolIds":[29],"utilityKeys":["Glasgow Coma Scale"],"canonical":true,"selectionNote":"Upgraded poster selected","asset":"posters/poster-024-glasgow-coma-scale.webp","questionIds":["Q0281","Q0282","Q0283","Q0284","Q0285","Q0286","Q0287","Q0288","Q0289","Q0290"],"questionCount":10,"meanHyp":81,"domains":["Nursing Fundamentals"],"job":"Trend detailed level of consciousness using eye, verbal and motor responses.","boundary":"GCS is detailed scoring; AVPU is rapid triage-level consciousness. Neither replaces a stroke screen.","handoffs":[{"tool":"AVPU","trigger":"Need rapid consciousness category rather than detailed score"},{"tool":"BE-FAST","trigger":"Stroke recognition is the task"}],"pearl":"Document E, V and M components; a total alone can hide clinically important change.","trap":"Do not use Glasgow Coma Scale as a rigid slogan; compare the patient's actual severity, timing, safety, scope, and response.","dataUri":"/assets/media/8efc1e9333f6b2b7.webp"},{"page":25,"id":"poster-025","slug":"glycemia-diabetes-acute-safety","title":"Glycemia & Diabetes Acute Safety","arabic":"سلامة سكر الدم والسكري الحاد","group":"labs","groupLabel":"Labs & monitoring","toolIds":[89],"utilityKeys":["Glycemia & Diabetes Acute Safety Lab"],"canonical":true,"selectionNote":"Upgraded poster selected","asset":"posters/poster-025-glycemia-diabetes-acute-safety.webp","questionIds":["Q0881","Q0882","Q0883","Q0884","Q0885","Q0886","Q0887","Q0888","Q0889","Q0890"],"questionCount":10,"meanHyp":92,"domains":["Adult Nursing"],"job":"Manage acute hypo/hyperglycemia safety including swallow/mental status, insulin/nutrition context, DKA/HHS clues and recheck.","boundary":"Glycemia Lab owns the acute glucose problem. Core Lab owns routine glucose pattern context; High-Alert owns medication-specific insulin safety when glucose crisis is not the whole case.","handoffs":[{"tool":"Core Laboratory Pattern Atlas","trigger":"The question is routine lab interpretation rather than acute management"},{"tool":"High-Alert & Special Medication Considerations Lab","trigger":"The task is insulin hold/give/monitor safety rather than the acute glycemia pathway"}],"pearl":"Endocrine emergencies are pattern-based: treat hypoglycemia immediately, DKA/HHS with fluids and protocolized insulin/electrolytes, and adrenal/thyroid crises with urgent supportive and hormone-specific therapy.","trap":"Avoid choosing an option based on one isolated cue; match the intervention to the patient's full clinical picture.","dataUri":"/assets/media/75b158e404d63389.webp"},{"page":26,"id":"poster-026","slug":"i-pass-handoff","title":"I-PASS Handoff","arabic":"تسليم الرعاية باستخدام I-PASS","group":"communication","groupLabel":"Communication & leadership","toolIds":[20],"utilityKeys":["I-PASS"],"canonical":true,"selectionNote":"Upgraded poster selected","asset":"posters/poster-026-i-pass-handoff.webp","questionIds":["Q0191","Q0192","Q0193","Q0194","Q0195","Q0196","Q0197","Q0198","Q0199","Q0200"],"questionCount":10,"meanHyp":77,"domains":["Nursing Management and Leadership"],"job":"Transfer responsibility with a structured handoff: illness severity, patient summary, action list, situational awareness, synthesis.","boundary":"I-PASS owns handoff/transfer of ongoing responsibility. SBAR owns focused issue escalation.","handoffs":[{"tool":"SBAR / ISBAR","trigger":"One current problem needs clinician escalation/report"},{"tool":"Closed-Loop Communication","trigger":"One urgent instruction needs confirmation"}],"pearl":"A safe handoff transfers both information and responsibility, including what to do if the patient worsens.","trap":"Do not use I-PASS Handoff as a rigid slogan; compare the patient's actual severity, timing, safety, scope, and response.","dataUri":"/assets/media/54e42ab36bf19379.webp"},{"page":28,"id":"poster-028","slug":"iv-fluid-types-selection","title":"IV Fluid Types & Selection","arabic":"أنواع السوائل الوريدية واختيارها","group":"medication","groupLabel":"Medication & infusion","toolIds":[45],"utilityKeys":["IV Fluid Types & Selection Tool"],"canonical":true,"selectionNote":"Upgraded poster selected","asset":"posters/poster-028-iv-fluid-types-selection.webp","questionIds":["Q0441","Q0442","Q0443","Q0444","Q0445","Q0446","Q0447","Q0448","Q0449","Q0450"],"questionCount":10,"meanHyp":77,"domains":["Nursing Fundamentals"],"job":"Choose the fluid family based on the 5R purpose: resuscitation, routine maintenance, replacement, redistribution, reassessment.","boundary":"Fluid Selection owns which fluid family fits the purpose. IV Therapy owns volume status/site/rate/response. Critical Lab owns dangerous electrolyte abnormalities.","handoffs":[{"tool":"IV Therapy & Fluid Balance Lab","trigger":"The question is volume status, I&O, IV site, rate or response"},{"tool":"Critical Lab & Electrolyte Prioritizer","trigger":"Electrolyte danger/ECG/symptoms drives urgency"}],"pearl":"Choose fluid by the physiologic problem, then reassess - tonicity alone is not the whole prescription.","trap":"Do not use IV Fluid Types & Selection as a rigid slogan; compare the patient's actual severity, timing, safety, scope, and response.","dataUri":"/assets/media/d7b02d431f2c43df.webp"},{"page":29,"id":"poster-029","slug":"iv-therapy-fluid-balance","title":"IV Therapy & Fluid Balance","arabic":"العلاج الوريدي وتوازن السوائل","group":"medication","groupLabel":"Medication & infusion","toolIds":[43],"utilityKeys":["IV Therapy & Fluid Balance Lab"],"canonical":true,"selectionNote":"Upgraded poster selected","asset":"posters/poster-029-iv-therapy-fluid-balance.webp","questionIds":["Q0421","Q0422","Q0423","Q0424","Q0425","Q0426","Q0427","Q0428","Q0429","Q0430"],"questionCount":10,"meanHyp":72,"domains":["Nursing Fundamentals"],"job":"Interpret volume status, I&O, IV site, rate/pump context, response and fluid-balance complications.","boundary":"IV Therapy owns patient volume/status and therapy response. Fluid Selection owns which fluid family; Pump Safety owns programming; Vascular Access owns device choice.","handoffs":[{"tool":"IV Fluid Types & Selection Tool","trigger":"The question is which fluid family/5R purpose"},{"tool":"Infusion Pump Safety Tool","trigger":"Pump setup/programming/alarm safety is the task"},{"tool":"Peripheral vs Central Vascular Access Decision Lab","trigger":"The question is which access device/route"}],"pearl":"IV fluid is a prescribed therapy: know which of the 5 Rs you are treating and reassess response.","trap":"Do not use IV Therapy & Fluid Balance Lab as a rigid slogan; compare the patient's actual severity, timing, safety, scope, and response.","dataUri":"/assets/media/a29d58083ec462b2.webp"},{"page":30,"id":"poster-030","slug":"infection-control-selector","title":"Infection Control Selector","arabic":"محدد مكافحة العدوى","group":"safety","groupLabel":"Safety & infection","toolIds":[42,109],"utilityKeys":["Infection Control Selector"],"canonical":true,"selectionNote":"Upgraded poster selected","asset":"posters/poster-030-infection-control-selector.webp","questionIds":["Q0411","Q0412","Q0413","Q0414","Q0415","Q0416","Q0417","Q0418","Q0419","Q0420","Q1081","Q1082","Q1083","Q1084","Q1085","Q1086","Q1087","Q1088","Q1089","Q1090"],"questionCount":20,"meanHyp":83,"domains":["Nursing Fundamentals"],"job":"Disease-specific isolation decision including route, exceptions, PPE, don/doff, transport and duration/context.","boundary":"This is the advanced selector. Use simple Isolation Precautions for a basic route/PPE family question; use WHO 5 Moments for hand-hygiene timing.","handoffs":[{"tool":"Isolation Precautions","trigger":"Only the basic contact/droplet/airborne category is needed"},{"tool":"WHO 5 Moments for Hand Hygiene","trigger":"The task is timing of hand hygiene"}],"pearl":"Select precautions from the disease/syndrome and transmission route, not from one memorized PPE list.","trap":"Do not use Infection Control Selector as a rigid slogan; compare the patient's actual severity, timing, safety, scope, and response.","dataUri":"/assets/media/9dbad2a4d0540f81.webp"},{"page":31,"id":"poster-031","slug":"infusion-pump-safety","title":"Infusion Pump Safety","arabic":"سلامة مضخة التسريب","group":"medication","groupLabel":"Medication & infusion","toolIds":[44],"utilityKeys":["Infusion Pump Safety Tool"],"canonical":true,"selectionNote":"Upgraded poster selected","asset":"posters/poster-031-infusion-pump-safety.webp","questionIds":["Q0431","Q0432","Q0433","Q0434","Q0435","Q0436","Q0437","Q0438","Q0439","Q0440"],"questionCount":10,"meanHyp":72,"domains":["Nursing Fundamentals"],"job":"Program, verify and troubleshoot infusion-pump delivery safely, including rate/volume/channel/alarm checks.","boundary":"Pump Safety owns the device. Math owns calculation; IV Therapy owns patient fluid response; High-Alert owns drug-specific safety gates.","handoffs":[{"tool":"Medication Math Lab","trigger":"Need to calculate the rate/dose first"},{"tool":"IV Therapy & Fluid Balance Lab","trigger":"The patient volume/site/response is the main issue"},{"tool":"High-Alert & Special Medication Considerations Lab","trigger":"Medication-specific hold/give/monitor rule dominates"}],"pearl":"The pump checks parameters; the nurse still checks the patient, drug, line, concentration, dose and response.","trap":"Do not use Infusion Pump Safety as a rigid slogan; compare the patient's actual severity, timing, safety, scope, and response.","dataUri":"/assets/media/8f05728952704bca.webp"},{"page":32,"id":"poster-032","slug":"isolation-precautions","title":"Isolation Precautions","arabic":"احتياطات العزل","group":"safety","groupLabel":"Safety & infection","toolIds":[24,109],"utilityKeys":["Isolation Precautions"],"canonical":true,"selectionNote":"Upgraded poster selected","asset":"posters/poster-032-isolation-precautions.webp","questionIds":["Q0231","Q0232","Q0233","Q0234","Q0235","Q0236","Q0237","Q0238","Q0239","Q0240","Q1081","Q1082","Q1083","Q1084","Q1085","Q1086","Q1087","Q1088","Q1089","Q1090"],"questionCount":20,"meanHyp":83,"domains":["Nursing Fundamentals"],"job":"Quick transmission-category and baseline PPE/placement framework for contact, droplet, airborne, and standard precautions.","boundary":"Use this for the quick precaution family. Use Infection Control Selector for disease-specific exceptions, PPE sequencing, duration, transport, or complex isolation decisions.","handoffs":[{"tool":"Infection Control Selector","trigger":"Disease-specific isolation/PPE/transport/don-doff is the real task"},{"tool":"WHO 5 Moments for Hand Hygiene","trigger":"The question asks timing of hand hygiene"}],"pearl":"Standard is the foundation; transmission-based precautions are added, sometimes in combination.","trap":"Do not use Isolation Precautions as a rigid slogan; compare the patient's actual severity, timing, safety, scope, and response.","dataUri":"/assets/media/18b9408179e62a33.webp"},{"page":33,"id":"poster-033","slug":"leadership-management-decision-matrix","title":"Leadership & Management Decision Matrix","arabic":"مصفوفة قرارات القيادة والإدارة","group":"communication","groupLabel":"Communication & leadership","toolIds":[58,112],"utilityKeys":["Leadership & Management Decision Matrix"],"canonical":true,"selectionNote":"Upgraded poster selected","asset":"posters/poster-033-leadership-management-decision-matrix.webp","questionIds":["Q0571","Q0572","Q0573","Q0574","Q0575","Q0576","Q0577","Q0578","Q0579","Q0580","Q1111","Q1112","Q1113","Q1114","Q1115","Q1116","Q1117","Q1118","Q1119","Q1120"],"questionCount":20,"meanHyp":84,"domains":["Nursing Management and Leadership"],"job":"Integrate assignment, delegation, staffing, prioritization, conflict and management decisions.","boundary":"Leadership Matrix owns multi-factor management questions. Use focused delegation/scope/legal tools when that single issue is the question.","handoffs":[{"tool":"Five Rights of Delegation","trigger":"Specific delegation decision"},{"tool":"Scope-of-Practice Filter","trigger":"Specific role/scope authorization"},{"tool":"Professional Practice & Legal Decision Coach","trigger":"Legal/ethical accountability is the dominant issue"}],"pearl":"Match leadership, staffing, delegation, supervision, and escalation to patient acuity, competence, scope, policy, and safety.","trap":"Delegation does not transfer accountability for appropriate delegation/supervision; safety overrides routine management work.","dataUri":"/assets/media/5449450885ee4897.webp"},{"page":34,"id":"poster-034","slug":"least-restrictive-least-invasive","title":"Least Restrictive & Least Invasive","arabic":"الأقل تقييداً والأقل تدخلاً","group":"priority","groupLabel":"Priority & nursing process","toolIds":[12,13],"utilityKeys":["Least Restrictive","Least Invasive"],"canonical":true,"selectionNote":"Upgraded poster selected","asset":"posters/poster-034-least-restrictive-least-invasive.webp","questionIds":["Q0111","Q0112","Q0113","Q0114","Q0115","Q0116","Q0117","Q0118","Q0119","Q0120","Q0121","Q0122","Q0123","Q0124","Q0125","Q0126","Q0127","Q0128","Q0129","Q0130"],"questionCount":20,"meanHyp":74,"domains":["Nursing Fundamentals"],"job":"Choose the lowest-restriction safety intervention, especially before restraints/seclusion, when safe. Choose the lower-burden procedure/intervention when options are similarly safe and effective.","boundary":"Restriction is about autonomy/freedom. Do not confuse it with procedural invasiveness. Safety emergencies can justify more restrictive measures. Invasiveness is physical/procedural burden; restriction is autonomy/freedom. They are not interchangeable.","handoffs":[{"tool":"Suicide & Psychiatric Safety Algorithm","trigger":"Immediate suicide/violence risk drives the safety plan"},{"tool":"Fall Prevention & Post-Fall Response Lab","trigger":"The problem is fall prevention rather than behavioral restriction"},{"tool":"Least Restrictive","trigger":"The issue is restraints/seclusion or freedom of movement"}],"pearl":"Least restrictive does not mean least effective; it means no more restriction than needed for safety.","trap":"Do not use Least Restrictive as a rigid slogan; compare the patient's actual severity, timing, safety, scope, and response.","dataUri":"/assets/media/cb6ea9d4f9d9bdfc.webp"},{"page":35,"id":"poster-035","slug":"maslow-clinical-priority-guide","title":"Maslow Clinical Priority Guide","arabic":"دليل ماسلو للأولوية السريرية","group":"priority","groupLabel":"Priority & nursing process","toolIds":[3],"utilityKeys":["Maslow"],"canonical":true,"selectionNote":"Upgraded poster selected","asset":"posters/poster-035-maslow-clinical-priority-guide.webp","questionIds":["Q0021","Q0022","Q0023","Q0024","Q0025","Q0026","Q0027","Q0028","Q0029","Q0030"],"questionCount":10,"meanHyp":77,"domains":["Nursing Fundamentals"],"job":"Tie-breaker among otherwise comparable stable needs by basic physiologic and safety needs before higher-level needs.","boundary":"Do not use Maslow to outrank physiologic instability. First screen stability/safety; use Maslow only when competing options are otherwise comparable.","handoffs":[{"tool":"Unstable Before Stable","trigger":"One patient is physiologically unstable"},{"tool":"Safety First","trigger":"Immediate avoidable harm dominates"}],"pearl":"Maslow helps rank comparable non-emergent needs; it never overrides an immediate life or safety threat.","trap":"Do not use Maslow Hierarchy as a rigid slogan; compare the patient's actual severity, timing, safety, scope, and response.","dataUri":"/assets/media/c4600d0e52152656.webp"},{"page":36,"id":"poster-036","slug":"medication-math-lab-foundations","title":"Medication Math Lab - Foundations","arabic":"مختبر حسابات الدواء - الأساسيات","group":"medication","groupLabel":"Medication & infusion","toolIds":[49],"utilityKeys":["Medication Math Lab"],"canonical":true,"selectionNote":"Upgraded poster selected","asset":"posters/poster-036-medication-math-lab-foundations.webp","questionIds":["Q0481","Q0482","Q0483","Q0484","Q0485","Q0486","Q0487","Q0488","Q0489","Q0490"],"questionCount":10,"meanHyp":82,"domains":["Nursing Fundamentals"],"job":"Calculate safe medication doses, rates, unit conversions and reasonableness checks.","boundary":"Math answers the number. Medication Rights verifies administration; High-Alert handles drug-specific safety gates; Pump Safety handles device programming.","handoffs":[{"tool":"Medication Rights","trigger":"No calculation is needed and administration checks drive the answer"},{"tool":"High-Alert & Special Medication Considerations Lab","trigger":"Drug-specific hold/give/monitor rule drives the case"},{"tool":"Infusion Pump Safety Tool","trigger":"Pump programming/device safety is the task"}],"pearl":"Safe medication math is D/H x Q after units match; correct arithmetic never overrides dose safety.","trap":"Do not reverse desired/have, use unsafe abbreviations, or let correct arithmetic override a safe-dose boundary.","dataUri":"/assets/media/2b5d1f062010d0bc.webp"},{"page":37,"id":"poster-037","slug":"medication-math-lab-advanced","title":"Medication Math Lab - Advanced","arabic":"مختبر حسابات الدواء - المتقدم","group":"medication","groupLabel":"Medication & infusion","toolIds":[50],"utilityKeys":["Medication Math Lab"],"canonical":true,"selectionNote":"Upgraded poster selected","asset":"posters/poster-037-medication-math-lab-advanced.webp","questionIds":["Q0491","Q0492","Q0493","Q0494","Q0495","Q0496","Q0497","Q0498","Q0499","Q0500"],"questionCount":10,"meanHyp":82,"domains":["Nursing Fundamentals"],"job":"Calculate safe medication doses, rates, unit conversions and reasonableness checks.","boundary":"Math answers the number. Medication Rights verifies administration; High-Alert handles drug-specific safety gates; Pump Safety handles device programming.","handoffs":[{"tool":"Medication Rights","trigger":"No calculation is needed and administration checks drive the answer"},{"tool":"High-Alert & Special Medication Considerations Lab","trigger":"Drug-specific hold/give/monitor rule drives the case"},{"tool":"Infusion Pump Safety Tool","trigger":"Pump programming/device safety is the task"}],"pearl":"Use the actual post-reconstitution concentration and actual tubing drop factor; verify plausibility before administration.","trap":"Do not infer a reconstituted concentration or drop factor; verify the actual product/tubing and final volume.","dataUri":"/assets/media/3fe723f4353ddc3e.webp"},{"page":38,"id":"poster-038","slug":"medication-administration-safety-checks","title":"Medication Administration Safety Checks","arabic":"فحوص سلامة إعطاء الدواء","group":"medication","groupLabel":"Medication & infusion","toolIds":[22,107],"utilityKeys":["Medication Rights"],"canonical":true,"selectionNote":"Upgraded poster selected","asset":"posters/poster-038-medication-administration-safety-checks.webp","questionIds":["Q0211","Q0212","Q0213","Q0214","Q0215","Q0216","Q0217","Q0218","Q0219","Q0220","Q1061","Q1062","Q1063","Q1064","Q1065","Q1066","Q1067","Q1068","Q1069","Q1070"],"questionCount":20,"meanHyp":90,"domains":["Nursing Fundamentals"],"job":"Routine medication-administration verification across patient, drug, dose, route, time and related rights.","boundary":"Medication Rights is the general administration gate. Use specialist tools when the stem is specifically identity, calculation, or high-alert drug safety.","handoffs":[{"tool":"Two Patient Identifiers","trigger":"Wrong-patient/identifier mismatch drives the case"},{"tool":"Medication Math Lab","trigger":"The task is a dose/rate calculation"},{"tool":"High-Alert & Special Medication Considerations Lab","trigger":"Drug-specific hold/give/monitor/escalate gate drives the answer"}],"pearl":"A mnemonic is a safety aid, not the whole medication-safety system.","trap":"Do not use Medication Administration Safety Checks / Rights as a rigid slogan; compare the patient's actual severity, timing, safety, scope, and response.","dataUri":"/assets/media/241ba71fb43d94b0.webp"},{"page":39,"id":"poster-039","slug":"ng-enteral-tube-safety","title":"NG / Enteral Tube Safety","arabic":"سلامة الأنبوب الأنفي المعدي والتغذية المعوية","group":"devices","groupLabel":"Devices & procedures","toolIds":[62],"utilityKeys":["NG / Enteral Tube Safety Tool"],"canonical":true,"selectionNote":"Upgraded poster selected","asset":"posters/poster-039-ng-enteral-tube-safety.webp","questionIds":["Q0611","Q0612","Q0613","Q0614","Q0615","Q0616","Q0617","Q0618","Q0619","Q0620"],"questionCount":10,"meanHyp":77,"domains":["Nursing Fundamentals"],"job":"Verify enteral-tube purpose/position/use, feeding/medication safety, aspiration risk and troubleshooting.","boundary":"NG/Enteral tool owns device-specific placement/use/feeding safety. Post-op owns broader postoperative tube/drain complications.","handoffs":[{"tool":"Post-op Complication & Tubes/Drains Troubleshooter","trigger":"The tube problem is one part of a broader postoperative complication differential"}],"pearl":"Never use the whoosh test; confirm placement by an accepted method before first use and stop use whenever displacement is suspected.","trap":"Never use the whoosh test or give feed/medication through a newly inserted or possibly displaced tube before accepted placement confirmation.","dataUri":"/assets/media/633944b7ed4ec075.webp"},{"page":40,"id":"poster-040","slug":"chain-of-command","title":"Chain of Command","arabic":"التسلسل الإداري للتصعيد","group":"communication","groupLabel":"Communication & leadership","toolIds":[18],"utilityKeys":["Chain of Command"],"canonical":true,"selectionNote":"Upgraded poster selected","asset":"posters/poster-040-chain-of-command.webp","questionIds":["Q0171","Q0172","Q0173","Q0174","Q0175","Q0176","Q0177","Q0178","Q0179","Q0180"],"questionCount":10,"meanHyp":78,"domains":["Nursing Management and Leadership"],"job":"Escalate an unresolved safety/clinical concern through organizational levels when the immediate route fails.","boundary":"Chain of Command begins after appropriate direct communication/escalation fails; it is not the first communication format.","handoffs":[{"tool":"CUS","trigger":"Need assertive language with the immediate team member"},{"tool":"SBAR / ISBAR","trigger":"Need to structure the clinical report"},{"tool":"Professional Practice & Legal Decision Coach","trigger":"Legal/ethical reporting/accountability is the core issue"}],"pearl":"Escalation is successful only when the safety problem is actually addressed.","trap":"Do not use Chain of Command as a rigid slogan; compare the patient's actual severity, timing, safety, scope, and response.","dataUri":"/assets/media/1f552694d40542d3.webp"},{"page":41,"id":"poster-041","slug":"scope-of-practice-filter","title":"Scope-of-Practice Filter","arabic":"مرشح نطاق الممارسة","group":"communication","groupLabel":"Communication & leadership","toolIds":[15],"utilityKeys":["Scope-of-Practice Filter"],"canonical":true,"selectionNote":"Upgraded poster selected","asset":"posters/poster-041-scope-of-practice-filter.webp","questionIds":["Q0141","Q0142","Q0143","Q0144","Q0145","Q0146","Q0147","Q0148","Q0149","Q0150"],"questionCount":10,"meanHyp":70,"domains":["Nursing Management and Leadership"],"job":"Check whether a role is authorized and competent to perform a task; retain RN-only assessment/teaching/judgment where required.","boundary":"Scope answers “may this role do it?”; delegation answers “should I delegate this task to this person in this situation?”","handoffs":[{"tool":"Five Rights of Delegation","trigger":"Authorization is clear and the question is whether/how to delegate"},{"tool":"Professional Practice & Legal Decision Coach","trigger":"The question is broader legal/ethical accountability"}],"pearl":"Scope sets the outer boundary; competence, policy, authorization and patient context determine whether you should act now.","trap":"Do not use Scope-of-Practice Filter as a rigid slogan; compare the patient's actual severity, timing, safety, scope, and response.","dataUri":"/assets/media/b54e7d3a7d72e5cb.webp"},{"page":42,"id":"poster-042","slug":"opqrst-pain-assessment","title":"OPQRST Pain Assessment","arabic":"تقييم الألم باستخدام OPQRST","group":"assessment","groupLabel":"Assessment & emergency","toolIds":[26],"utilityKeys":["OPQRST"],"canonical":true,"selectionNote":"Upgraded poster selected","asset":"posters/poster-042-opqrst-pain-assessment.webp","questionIds":["Q0251","Q0252","Q0253","Q0254","Q0255","Q0256","Q0257","Q0258","Q0259","Q0260"],"questionCount":10,"meanHyp":78,"domains":["Nursing Fundamentals"],"job":"Characterize a current symptom (especially pain) by onset, provocation/palliation, quality, region/radiation, severity, timing.","boundary":"OPQRST deepens one symptom. SAMPLE gathers the broader emergency history.","handoffs":[{"tool":"SAMPLE","trigger":"The question asks for broader history/allergies/meds/past history/last intake/events"}],"pearl":"Characterize the symptom without delaying care for a red-flag emergency.","trap":"Do not use OPQRST Pain Assessment as a rigid slogan; compare the patient's actual severity, timing, safety, scope, and response.","dataUri":"/assets/media/06ed95e068ffe992.webp"},{"page":43,"id":"poster-043","slug":"oxygenation-oxygen-therapy-suctioning","title":"Oxygenation, Oxygen Therapy & Suctioning","arabic":"الأكسجة والعلاج بالأكسجين والشفط","group":"assessment","groupLabel":"Assessment & emergency","toolIds":[37,116],"utilityKeys":["Oxygenation, Oxygen Therapy & Suctioning Decision Lab"],"canonical":true,"selectionNote":"Upgraded poster selected","asset":"posters/poster-043-oxygenation-oxygen-therapy-suctioning.webp","questionIds":["Q0361","Q0362","Q0363","Q0364","Q0365","Q0366","Q0367","Q0368","Q0369","Q0370","Q1151","Q1152","Q1153","Q1154","Q1155","Q1156","Q1157","Q1158","Q1159","Q1160"],"questionCount":20,"meanHyp":94,"domains":["Adult Nursing"],"job":"Choose oxygenation assessment, oxygen device/flow strategy, suctioning indications/safety and reassessment.","boundary":"Oxygenation Lab owns oxygen/suctioning decisions. Deterioration owns broader instability; Trach Lab owns stoma/trach emergencies; ABG owns acid-base interpretation.","handoffs":[{"tool":"Deterioration & First-Action Coach","trigger":"Several systems are deteriorating and oxygen is only one clue"},{"tool":"Tracheostomy Emergency & Care Reasoning Lab","trigger":"Tracheostomy/laryngectomy anatomy or trach emergency drives the case"},{"tool":"ABG Stepwise Interpreter","trigger":"The task is acid-base interpretation"}],"pearl":"SpO2 tells you oxygenation, not CO2 clearance or adequacy of ventilation.","trap":"Do not use Oxygenation, Oxygen Therapy & Suctioning as a rigid slogan; compare the patient's actual severity, timing, safety, scope, and response.","dataUri":"/assets/media/281b554f54ba2a4d.webp"},{"page":44,"id":"poster-044","slug":"patient-safety-event-sentinel-event","title":"Patient Safety Event & Sentinel Event","arabic":"حدث سلامة المريض والحدث الجسيم","group":"safety","groupLabel":"Safety & infection","toolIds":[113],"utilityKeys":["Patient Safety Event & Sentinel Event Decision Lab"],"canonical":true,"selectionNote":"Upgraded poster selected","asset":"posters/poster-044-patient-safety-event-sentinel-event.webp","questionIds":["Q1121","Q1122","Q1123","Q1124","Q1125","Q1126","Q1127","Q1128","Q1129","Q1130"],"questionCount":10,"meanHyp":94,"domains":["Nursing Management and Leadership"],"job":"Respond after an error/near miss/adverse/sentinel event: protect patient, classify, document/report, disclose/escalate and analyze systems.","boundary":"Safety First is prevention before harm. This tool begins when an event or near miss has occurred and the task is response/reporting/system learning.","handoffs":[{"tool":"Safety First","trigger":"No event has occurred"},{"tool":"Fall Prevention & Post-Fall Response Lab","trigger":"The task is patient-level fall prevention/post-fall assessment rather than event governance"}],"pearl":"No harm is not the same as no learning opportunity.","trap":"Safety reporting should focus on the event and system, not public blame in the clinical record.","dataUri":"/assets/media/3e8e06a20e427fdb.webp"},{"page":45,"id":"poster-045","slug":"pediatric-newborn-rapid-pattern-atlas","title":"Pediatric & Newborn Rapid Pattern Atlas","arabic":"أطلس الأنماط السريعة للأطفال وحديثي الولادة","group":"maternal","groupLabel":"Maternal & pediatrics","toolIds":[60,134,135,136,137],"utilityKeys":["Pediatric & Newborn Rapid Pattern Atlas"],"canonical":true,"selectionNote":"Upgraded poster selected","asset":"posters/poster-045-pediatric-newborn-rapid-pattern-atlas.webp","questionIds":["Q0591","Q0592","Q0593","Q0594","Q0595","Q0596","Q0597","Q0598","Q0599","Q0600","Q1316","Q1317","Q1318","Q1319","Q1320","Q1321","Q1322","Q1323","Q1324","Q1325","Q1326","Q1327","Q1328","Q1329","Q1330","Q1331","Q1332","Q1333","Q1334","Q1335","Q1336","Q1337","Q1338","Q1339","Q1340","Q1341","Q1342","Q1343","Q1344","Q1345","Q1346","Q1347","Q1348","Q1349","Q1350"],"questionCount":45,"meanHyp":94,"domains":["Maternal-Child Nursing"],"job":"Recognize broader pediatric/newborn age-specific patterns, red flags and first actions.","boundary":"The Atlas owns broader age-specific patterns. PAT is first-look triage; APGAR is newborn adaptation scoring.","handoffs":[{"tool":"Pediatric Assessment Triangle","trigger":"Need immediate first impression only"},{"tool":"APGAR","trigger":"Need the neonatal adaptation score"}],"pearl":"Use age- and transition-specific patterns; deterioration may present before hypotension, and neonatal oxygen targets change minute by minute after birth.","trap":"Do not apply adult vital-sign/oxygen targets to newborn transition or interpret decreasing respiratory effort as improvement without context.","dataUri":"/assets/media/1a0e713d438d6263.webp"},{"page":46,"id":"poster-046","slug":"pediatric-assessment-triangle","title":"Pediatric Assessment Triangle","arabic":"مثلث تقييم الطفل","group":"maternal","groupLabel":"Maternal & pediatrics","toolIds":[31],"utilityKeys":["Pediatric Assessment Triangle"],"canonical":true,"selectionNote":"Upgraded poster selected","asset":"posters/poster-046-pediatric-assessment-triangle.webp","questionIds":["Q0301","Q0302","Q0303","Q0304","Q0305","Q0306","Q0307","Q0308","Q0309","Q0310"],"questionCount":10,"meanHyp":89,"domains":["Maternal-Child Nursing"],"job":"Form an immediate pediatric first impression from appearance, work of breathing, and circulation to skin.","boundary":"PAT owns the first-look pediatric impression before hands-on details. The Pediatric/Newborn Atlas owns broader age-specific pattern recognition and management branches.","handoffs":[{"tool":"Pediatric & Newborn Rapid Pattern Atlas","trigger":"Need broader pediatric/newborn pattern interpretation after the first impression"}],"pearl":"Observe before your examination changes the child behavior.","trap":"Do not use Pediatric Assessment Triangle as a rigid slogan; compare the patient's actual severity, timing, safety, scope, and response.","dataUri":"/assets/media/b9be447d97e30b86.webp"},{"page":47,"id":"poster-047","slug":"peripheral-vs-central-vascular-access-decision-lab","title":"Peripheral vs Central Vascular Access Decision Lab","arabic":"مختبر قرار الوصول الوعائي الطرفي مقابل المركزي","group":"devices","groupLabel":"Devices & procedures","toolIds":[46,47],"utilityKeys":["Peripheral vs Central Vascular Access Decision Lab"],"canonical":true,"selectionNote":"Selected replacement: clearer device-selection nuance, stronger daily reassessment, fewer unsafe absolute cutoffs, and explicit switch-tool guidance.","asset":"posters/poster-047-peripheral-vs-central-vascular-access-decision-lab.webp","questionIds":["Q0451","Q0452","Q0453","Q0454","Q0455","Q0456","Q0457","Q0458","Q0459","Q0460","Q0461","Q0462","Q0463","Q0464","Q0465","Q0466","Q0467","Q0468","Q0469","Q0470"],"questionCount":20,"meanHyp":73,"domains":["Nursing Fundamentals"],"job":"Choose peripheral, midline, PICC or central access from therapy, duration, infusate and device/tip requirements.","boundary":"Vascular Access owns device selection. IV Therapy owns patient response/site complications; Pump Safety owns delivery-device programming.","handoffs":[{"tool":"IV Therapy & Fluid Balance Lab","trigger":"The access device is already chosen and the problem is site/volume/rate/response"},{"tool":"Infusion Pump Safety Tool","trigger":"The access is appropriate and pump programming/delivery is the problem"}],"pearl":"Right device is therapy plus duration plus patient plus vein plus risk - not one magic pH/osmolarity number.","trap":"Do not use Peripheral vs Central Vascular Access as a rigid slogan; compare the patient's actual severity, timing, safety, scope, and response.","dataUri":"/assets/media/86f3795d41571472.webp"},{"page":48,"id":"poster-048","slug":"post-op-complication-lab","title":"Post-Op Complication Lab","arabic":"مختبر مضاعفات ما بعد الجراحة","group":"devices","groupLabel":"Devices & procedures","toolIds":[41,119],"utilityKeys":["Post-op Complication & Tubes/Drains Troubleshooter"],"canonical":true,"selectionNote":"Upgraded poster selected","asset":"posters/poster-048-post-op-complication-lab.webp","questionIds":["Q0401","Q0402","Q0403","Q0404","Q0405","Q0406","Q0407","Q0408","Q0409","Q0410","Q1181","Q1182","Q1183","Q1184","Q1185","Q1186","Q1187","Q1188","Q1189","Q1190"],"questionCount":20,"meanHyp":87,"domains":["Adult Nursing"],"job":"Recognize postoperative complications and troubleshoot drains/tubes in postoperative context.","boundary":"Post-op tool owns postoperative complication context. Device-specific tools take over when the device itself—not postoperative differential—is the core problem.","handoffs":[{"tool":"NG / Enteral Tube Safety Tool","trigger":"NG/enteral placement/use/feeding safety is the main task"},{"tool":"Urinary Catheter & CAUTI Safety Tool","trigger":"Catheter/CAUTI/drainage system is the main task"},{"tool":"Tracheostomy Emergency & Care Reasoning Lab","trigger":"Airway/stoma/trach emergency is the main task"}],"pearl":"Postoperative does not mean abnormal is expected; new ABC deterioration is an emergency until proven otherwise.","trap":"Do not use Post-Op Complication Lab as a rigid slogan; compare the patient's actual severity, timing, safety, scope, and response.","dataUri":"/assets/media/db6ec543a6a9056d.webp"},{"page":49,"id":"poster-049","slug":"professional-practice-legal-decision-coach","title":"Professional Practice & Legal Decision Coach","arabic":"مدرب الممارسة المهنية والقرار القانوني","group":"mental","groupLabel":"Mental health & professional","toolIds":[65,113],"utilityKeys":["Professional Practice & Legal Decision Coach"],"canonical":true,"selectionNote":"Upgraded poster selected","asset":"posters/poster-049-professional-practice-legal-decision-coach.webp","questionIds":["Q0641","Q0642","Q0643","Q0644","Q0645","Q0646","Q0647","Q0648","Q0649","Q0650","Q1121","Q1122","Q1123","Q1124","Q1125","Q1126","Q1127","Q1128","Q1129","Q1130"],"questionCount":20,"meanHyp":83,"domains":["Nursing Management and Leadership"],"job":"Reason through consent, confidentiality, documentation, scope/accountability, reporting and legal/ethical professional duties.","boundary":"Use the focused tools when the issue is only scope, escalation route or management assignment. Use this coach when legal/ethical accountability itself drives the answer.","handoffs":[{"tool":"Scope-of-Practice Filter","trigger":"Only role authorization/competency is being tested"},{"tool":"Chain of Command","trigger":"The task is escalation of an unresolved concern"},{"tool":"Leadership & Management Decision Matrix","trigger":"The task is staffing/assignment/management"}],"pearl":"Anchor SNLE legal/professional decisions in Saudi law, SCFHS scope/ethics, MOH consent/rights, CBAHI standards, and organizational policy.","trap":"Do not use U.S. state-law language as the governing SNLE framework; localize to Saudi law, SCFHS, MOH, CBAHI, and facility policy.","dataUri":"/assets/media/c0074fbf62c22c58.webp"},{"page":50,"id":"poster-050","slug":"psychiatric-nursing-decision-safety-guide","title":"Psychiatric Nursing Decision & Safety Guide","arabic":"دليل القرار والسلامة في التمريض النفسي","group":"mental","groupLabel":"Mental health & professional","toolIds":[124,125],"utilityKeys":[],"canonical":true,"selectionNote":"Added as a distinct broad psychiatric reasoning tool; suicide-specific decisions remain in their own algorithm.","asset":"posters/poster-050-psychiatric-nursing-decision-safety-guide.webp","questionIds":["Q1226","Q1227","Q1228","Q1229","Q1230","Q1231","Q1232","Q1233","Q1234","Q1235","Q1236","Q1237","Q1238","Q1239","Q1240","Q1241","Q1242","Q1243","Q1244","Q1245"],"questionCount":20,"meanHyp":93,"domains":["Adult Nursing"],"job":"","boundary":"Use the poster to frame the decision, then follow the patient data, local policy, scope, and escalation pathway.","handoffs":[],"pearl":"Ask directly about suicide; vague reassurance is not a safety assessment.","trap":"A “no-suicide promise” is not a substitute for risk assessment and observation.","dataUri":"/assets/media/bea287513215346c.webp"},{"page":51,"id":"poster-051","slug":"race-pass-fire-safety","title":"RACE & PASS Fire Safety","arabic":"سلامة الحريق RACE وPASS","group":"safety","groupLabel":"Safety & infection","toolIds":[32,33],"utilityKeys":["RACE","PASS"],"canonical":true,"selectionNote":"Upgraded poster selected","asset":"posters/poster-051-race-pass-fire-safety.webp","questionIds":["Q0311","Q0312","Q0313","Q0314","Q0315","Q0316","Q0317","Q0318","Q0319","Q0320","Q0321","Q0322","Q0323","Q0324","Q0325","Q0326","Q0327","Q0328","Q0329","Q0330"],"questionCount":20,"meanHyp":72,"domains":["Nursing Fundamentals"],"job":"Sequence immediate response to a fire/smoke event: Rescue, Alarm, Contain, Extinguish/Evacuate. Operate a fire extinguisher: Pull, Aim, Squeeze, Sweep.","boundary":"RACE owns the overall fire response. PASS only owns extinguisher operation. PASS is not the whole fire-response plan; use it only after the situation calls for extinguisher use.","handoffs":[{"tool":"PASS","trigger":"The specific question is how to operate the extinguisher"},{"tool":"RACE","trigger":"The question asks the overall fire-response sequence"}],"pearl":"People before property: Rescue immediate danger, Alarm, Confine, then Extinguish/Evacuate according to safety and policy.","trap":"Do not use RACE Fire Response as a rigid slogan; compare the patient's actual severity, timing, safety, scope, and response.","dataUri":"/assets/media/f4949970da5c8f7c.webp"},{"page":52,"id":"poster-052","slug":"research-ebp-quick-filter","title":"Research & EBP Quick Filter","arabic":"مرشح البحث والممارسة المبنية على الدليل","group":"mental","groupLabel":"Mental health & professional","toolIds":[61,114],"utilityKeys":["Research & EBP Quick Filter"],"canonical":true,"selectionNote":"Upgraded poster selected","asset":"posters/poster-052-research-ebp-quick-filter.webp","questionIds":["Q0601","Q0602","Q0603","Q0604","Q0605","Q0606","Q0607","Q0608","Q0609","Q0610","Q1131","Q1132","Q1133","Q1134","Q1135","Q1136","Q1137","Q1138","Q1139","Q1140"],"questionCount":20,"meanHyp":76,"domains":["Nursing Management and Leadership"],"job":"Identify research design, evidence hierarchy, PICO/EBP steps and appraisal direction.","boundary":"Research/EBP owns evidence questions, not community-prevention action selection.","handoffs":[{"tool":"Saudi Community & Prevention Selector","trigger":"The stem asks what prevention/community action to implement"}],"pearl":"Ask, acquire, appraise, apply, and assess; separate evidence hierarchy from study quality and reporting guidelines from appraisal tools.","trap":"Do not confuse evidence level with quality, or reporting guidelines (e.g., STROBE/PRISMA) with critical-appraisal tools.","dataUri":"/assets/media/f3236442c57ce0f4.webp"},{"page":53,"id":"poster-053","slug":"sample-emergency-history","title":"SAMPLE Emergency History","arabic":"التاريخ الإسعافي SAMPLE","group":"assessment","groupLabel":"Assessment & emergency","toolIds":[27],"utilityKeys":["SAMPLE"],"canonical":true,"selectionNote":"Upgraded poster selected","asset":"posters/poster-053-sample-emergency-history.webp","questionIds":["Q0261","Q0262","Q0263","Q0264","Q0265","Q0266","Q0267","Q0268","Q0269","Q0270"],"questionCount":10,"meanHyp":80,"domains":["Nursing Fundamentals"],"job":"Gather a concise emergency history: Symptoms, Allergies, Medications, Past history, Last intake, Events.","boundary":"SAMPLE is broad history; OPQRST is detailed symptom characterization.","handoffs":[{"tool":"OPQRST","trigger":"One symptom needs detailed characterization"}],"pearl":"SAMPLE gives context; OPQRST characterizes the symptom.","trap":"Do not use SAMPLE History as a rigid slogan; compare the patient's actual severity, timing, safety, scope, and response.","dataUri":"/assets/media/4c2112029f12b0c9.webp"},{"page":54,"id":"poster-054","slug":"sbar-isbar","title":"SBAR / ISBAR","arabic":"التواصل المنظم SBAR / ISBAR","group":"communication","groupLabel":"Communication & leadership","toolIds":[16],"utilityKeys":["SBAR / ISBAR"],"canonical":true,"selectionNote":"Upgraded poster selected","asset":"posters/poster-054-sbar-isbar.webp","questionIds":["Q0151","Q0152","Q0153","Q0154","Q0155","Q0156","Q0157","Q0158","Q0159","Q0160"],"questionCount":10,"meanHyp":78,"domains":["Nursing Management and Leadership"],"job":"Structure a focused clinical report/escalation to another clinician about a current issue.","boundary":"SBAR organizes the content of a report. It is not a full shift handoff, graded assertion, escalation ladder, or read-back loop.","handoffs":[{"tool":"I-PASS","trigger":"Transfer of ongoing patient responsibility/handoff"},{"tool":"CUS","trigger":"Need escalating assertive safety language"},{"tool":"Chain of Command","trigger":"Concern remains unresolved"},{"tool":"Closed-Loop Communication","trigger":"Urgent message needs confirmation/read-back"}],"pearl":"ABCDE manages the patient; SBAR organizes the message.","trap":"Do not use SBAR / ISBAR as a rigid slogan; compare the patient's actual severity, timing, safety, scope, and response.","dataUri":"/assets/media/2cd308e1677ae4db.webp"},{"page":55,"id":"poster-055","slug":"safety-first","title":"Safety First","arabic":"السلامة أولاً","group":"priority","groupLabel":"Priority & nursing process","toolIds":[4],"utilityKeys":["Safety First"],"canonical":true,"selectionNote":"Upgraded poster selected","asset":"posters/poster-055-safety-first.webp","questionIds":["Q0031","Q0032","Q0033","Q0034","Q0035","Q0036","Q0037","Q0038","Q0039","Q0040"],"questionCount":10,"meanHyp":75,"domains":["Nursing Fundamentals"],"job":"Choose the option that prevents the most immediate avoidable harm when no more specific emergency framework already owns the case.","boundary":"Safety First is a broad hazard filter, not a substitute for ABCDE/CAB, emergency action, or event-reporting frameworks.","handoffs":[{"tool":"Emergency Exception","trigger":"Delay itself is dangerous"},{"tool":"Patient Safety Event & Sentinel Event Decision Lab","trigger":"An error/event has already occurred and response/reporting is the task"}],"pearl":"Remove or control the most immediate preventable harm first, then continue the appropriate clinical framework.","trap":"Do not use Safety First as a rigid slogan; compare the patient's actual severity, timing, safety, scope, and response.","dataUri":"/assets/media/4415a33e2d0dfb64.webp"},{"page":56,"id":"poster-056","slug":"special-medications-diseases-laboratory-considerations","title":"Special Medications, Diseases & Laboratory Considerations","arabic":"اعتبارات الأدوية الخاصة والأمراض والتحاليل","group":"medication","groupLabel":"Medication & infusion","toolIds":[51,56,111],"utilityKeys":["High-Alert & Special Medication Considerations Lab"],"canonical":true,"selectionNote":"Upgraded poster selected","asset":"posters/poster-056-special-medications-diseases-laboratory-considerations.webp","questionIds":["Q0501","Q0502","Q0503","Q0504","Q0505","Q0506","Q0507","Q0508","Q0509","Q0510","Q0551","Q0552","Q0553","Q0554","Q0555","Q0556","Q0557","Q0558","Q0559","Q0560","Q1101","Q1102","Q1103","Q1104","Q1105","Q1106","Q1107","Q1108","Q1109","Q1110"],"questionCount":30,"meanHyp":86,"domains":["Nursing Fundamentals"],"job":"Drug-specific GIVE / HOLD-QUESTION / MONITOR-VERIFY / ESCALATE safety gates for high-alert medications.","boundary":"This tool owns drug-specific safety. Routine administration, calculation, acute glucose crisis, and pump programming each have their own tool.","handoffs":[{"tool":"Medication Rights","trigger":"Routine medication verification only"},{"tool":"Medication Math Lab","trigger":"Calculation is the task"},{"tool":"Glycemia & Diabetes Acute Safety Lab","trigger":"Acute hypo/hyperglycemia management is the main problem"},{"tool":"Infusion Pump Safety Tool","trigger":"Device programming/pump safety is the main problem"}],"pearl":"Medication-laboratory relationships are indication-, assay-, patient-, and protocol-specific; avoid universal hold thresholds.","trap":"Avoid universal INR, aPTT, platelet, or medication-hold thresholds; indication and protocol matter.","dataUri":"/assets/media/7fa192fbc7eb6ec7.webp"},{"page":57,"id":"poster-057","slug":"suicide-psychiatric-safety-algorithm","title":"Suicide & Psychiatric Safety Algorithm","arabic":"خوارزمية سلامة الانتحار والطب النفسي","group":"mental","groupLabel":"Mental health & professional","toolIds":[93],"utilityKeys":["Suicide & Psychiatric Safety Algorithm"],"canonical":true,"selectionNote":"Upgraded poster selected","asset":"posters/poster-057-suicide-psychiatric-safety-algorithm.webp","questionIds":["Q0921","Q0922","Q0923","Q0924","Q0925","Q0926","Q0927","Q0928","Q0929","Q0930"],"questionCount":10,"meanHyp":93,"domains":["Adult Nursing"],"job":"Assess psychiatric/suicide safety, immediate risk, observation/environment and escalation.","boundary":"Safety overrides therapeutic phrasing or least-restrictive preferences when imminent risk is present.","handoffs":[{"tool":"Least Restrictive","trigger":"Risk is controlled and the question is choosing the least restrictive safe intervention"},{"tool":"Therapeutic Communication Simulator","trigger":"No immediate safety threat and the task is therapeutic response"}],"pearl":"Direct suicide assessment does not create suicidal thoughts; imminent risk requires immediate safety measures, observation, means restriction, and escalation.","trap":"Avoid choosing an option based on one isolated cue; match the intervention to the patient's full clinical picture.","dataUri":"/assets/media/2ddc7b0d01ddadb2.webp"},{"page":58,"id":"poster-058","slug":"teach-back","title":"Teach-Back","arabic":"التحقق من الفهم بإعادة الشرح","group":"communication","groupLabel":"Communication & leadership","toolIds":[21],"utilityKeys":["Teach-Back"],"canonical":true,"selectionNote":"Upgraded poster selected","asset":"posters/poster-058-teach-back.webp","questionIds":["Q0201","Q0202","Q0203","Q0204","Q0205","Q0206","Q0207","Q0208","Q0209","Q0210"],"questionCount":10,"meanHyp":72,"domains":["Nursing Fundamentals"],"job":"Verify patient/caregiver understanding by asking them to explain or demonstrate instructions in their own words.","boundary":"Teach-Back evaluates learning after education. Therapeutic Communication focuses on how to respond supportively in a patient conversation.","handoffs":[{"tool":"Therapeutic Communication Simulator","trigger":"The task is an empathic/therapeutic response rather than checking learning"}],"pearl":"Ask, reteach differently if needed, and check again.","trap":"Do not use Teach-Back as a rigid slogan; compare the patient's actual severity, timing, safety, scope, and response.","dataUri":"/assets/media/cb1fe77d1e63f386.webp"},{"page":59,"id":"poster-059","slug":"therapeutic-communication-simulator","title":"Therapeutic Communication Simulator","arabic":"محاكي التواصل العلاجي","group":"mental","groupLabel":"Mental health & professional","toolIds":[94],"utilityKeys":["Therapeutic Communication Simulator"],"canonical":true,"selectionNote":"Upgraded poster selected","asset":"posters/poster-059-therapeutic-communication-simulator.webp","questionIds":["Q0931","Q0932","Q0933","Q0934","Q0935","Q0936","Q0937","Q0938","Q0939","Q0940"],"questionCount":10,"meanHyp":78,"domains":["Adult Nursing"],"job":"Choose patient-facing therapeutic responses that acknowledge, explore and avoid blocking communication.","boundary":"This is patient-facing therapeutic dialogue. Teach-Back checks learning; SBAR is clinician-to-clinician communication.","handoffs":[{"tool":"Teach-Back","trigger":"Need to verify understanding after education"},{"tool":"SBAR / ISBAR","trigger":"Need structured clinician communication"}],"pearl":"Therapeutic communication is patient-centered, nonjudgmental, clear, and boundaried; avoid false reassurance, arguing, excessive advice, and meeting the nurse's needs.","trap":"Avoid choosing an option based on one isolated cue; match the intervention to the patient's full clinical picture.","dataUri":"/assets/media/5eb43b20b7b82ca3.webp"},{"page":60,"id":"poster-060","slug":"tracheostomy-emergency-care","title":"Tracheostomy Emergency & Care","arabic":"طوارئ ورعاية فغر الرغامى","group":"devices","groupLabel":"Devices & procedures","toolIds":[39,122],"utilityKeys":["Tracheostomy Emergency & Care Reasoning Lab"],"canonical":true,"selectionNote":"Upgraded poster selected","asset":"posters/poster-060-tracheostomy-emergency-care.webp","questionIds":["Q0381","Q0382","Q0383","Q0384","Q0385","Q0386","Q0387","Q0388","Q0389","Q0390","Q1211","Q1212","Q1213","Q1214","Q1215","Q1216","Q1217","Q1218","Q1219","Q1220"],"questionCount":20,"meanHyp":97,"domains":["Adult Nursing"],"job":"Differentiate tracheostomy/laryngectomy anatomy, assess patency, manage obstruction/displacement/bleeding and routine trach care.","boundary":"Trach Lab owns neck-airway anatomy/device emergencies. Oxygen Lab owns general oxygen/suctioning; Post-op owns broader postoperative tube/drain complications.","handoffs":[{"tool":"Oxygenation, Oxygen Therapy & Suctioning Decision Lab","trigger":"No trach-specific anatomy/device problem"},{"tool":"Post-op Complication & Tubes/Drains Troubleshooter","trigger":"The trach is one of several postoperative complications rather than the main airway problem"}],"pearl":"In a tracheostomy emergency, oxygenation and patency come before routine tube-care steps.","trap":"Do not use Tracheostomy Emergency & Care as a rigid slogan; compare the patient's actual severity, timing, safety, scope, and response.","dataUri":"/assets/media/39bb2db2330a396c.webp"},{"page":61,"id":"poster-061","slug":"tubes-drains-troubleshooter","title":"Tubes / Drains Troubleshooter","arabic":"دليل استكشاف مشكلات الأنابيب والمصارف","group":"devices","groupLabel":"Devices & procedures","toolIds":[120],"utilityKeys":["Post-op Complication & Tubes/Drains Troubleshooter"],"canonical":true,"selectionNote":"Split from the older combined post-op popup so device troubleshooting has a focused workflow.","asset":"posters/poster-061-tubes-drains-troubleshooter.webp","questionIds":["Q1191","Q1192","Q1193","Q1194","Q1195","Q1196","Q1197","Q1198","Q1199","Q1200"],"questionCount":10,"meanHyp":90,"domains":["Adult Nursing"],"job":"Recognize postoperative complications and troubleshoot drains/tubes in postoperative context.","boundary":"Post-op tool owns postoperative complication context. Device-specific tools take over when the device itself—not postoperative differential—is the core problem.","handoffs":[{"tool":"NG / Enteral Tube Safety Tool","trigger":"NG/enteral placement/use/feeding safety is the main task"},{"tool":"Urinary Catheter & CAUTI Safety Tool","trigger":"Catheter/CAUTI/drainage system is the main task"},{"tool":"Tracheostomy Emergency & Care Reasoning Lab","trigger":"Airway/stoma/trach emergency is the main task"}],"pearl":"Closed-suction drains work only when the reservoir is compressed and the system is intact.","trap":"Do not alter or aggressively manipulate drain tubing without indication.","dataUri":"/assets/media/eb64f46986454900.webp"},{"page":62,"id":"poster-062","slug":"two-patient-identifiers","title":"Two Patient Identifiers","arabic":"معرّفان معتمدان للمريض","group":"safety","groupLabel":"Safety & infection","toolIds":[23],"utilityKeys":["Two Patient Identifiers"],"canonical":true,"selectionNote":"Upgraded poster selected","asset":"posters/poster-062-two-patient-identifiers.webp","questionIds":["Q0221","Q0222","Q0223","Q0224","Q0225","Q0226","Q0227","Q0228","Q0229","Q0230"],"questionCount":10,"meanHyp":72,"domains":["Nursing Fundamentals"],"job":"Verify two approved person-specific identifiers before identity-sensitive care.","boundary":"This tool owns identity verification before care. If wrong-patient harm already occurred, switch to event response/reporting.","handoffs":[{"tool":"Medication Rights","trigger":"The broader medication-administration sequence is the task"},{"tool":"Patient Safety Event & Sentinel Event Decision Lab","trigger":"A wrong-patient event has already occurred"}],"pearl":"No match means no medication, specimen, procedure or transfusion until identity is resolved.","trap":"Do not use Two Patient Identifiers as a rigid slogan; compare the patient's actual severity, timing, safety, scope, and response.","dataUri":"/assets/media/8d64921d78cf79aa.webp"},{"page":63,"id":"poster-063","slug":"unexpected-before-expected","title":"Unexpected Before Expected","arabic":"غير المتوقع قبل المتوقع","group":"priority","groupLabel":"Priority & nursing process","toolIds":[8],"utilityKeys":["Unexpected Before Expected"],"canonical":true,"selectionNote":"Upgraded poster selected","asset":"posters/poster-063-unexpected-before-expected.webp","questionIds":["Q0071","Q0072","Q0073","Q0074","Q0075","Q0076","Q0077","Q0078","Q0079","Q0080"],"questionCount":10,"meanHyp":78,"domains":["Nursing Fundamentals"],"job":"Identify an abnormal/unexpected finding that needs follow-up before an expected finding.","boundary":"This is about expectedness, not simply newness. Once an unexpected finding is identified, a focused assessment or emergency framework may take over.","handoffs":[{"tool":"Assess Before Acting","trigger":"A focused assessment is needed before intervention"},{"tool":"Emergency Exception","trigger":"Unexpected finding already establishes an immediate life threat"}],"pearl":"Unexpected is an alarm; severity determines how urgently you respond.","trap":"Do not use Unexpected Before Expected as a rigid slogan; compare the patient's actual severity, timing, safety, scope, and response.","dataUri":"/assets/media/19ba53888b443762.webp"},{"page":64,"id":"poster-064","slug":"unstable-before-stable","title":"Unstable Before Stable","arabic":"غير المستقر قبل المستقر","group":"priority","groupLabel":"Priority & nursing process","toolIds":[5],"utilityKeys":["Unstable Before Stable"],"canonical":true,"selectionNote":"Upgraded poster selected","asset":"posters/poster-064-unstable-before-stable.webp","questionIds":["Q0041","Q0042","Q0043","Q0044","Q0045","Q0046","Q0047","Q0048","Q0049","Q0050"],"questionCount":10,"meanHyp":79,"domains":["Nursing Fundamentals"],"job":"Rank patients/problems by current physiologic instability before chronology or convenience.","boundary":"Stability is the first discriminator. Acute-vs-chronic is only useful after stability is comparable.","handoffs":[{"tool":"Acute Before Chronic","trigger":"Patients are comparably stable and chronology decides"},{"tool":"Deterioration & First-Action Coach","trigger":"Single patient with complex deterioration clues"}],"pearl":"Unstable means current or evolving threat, not merely an abnormal number.","trap":"Do not use Unstable Before Stable as a rigid slogan; compare the patient's actual severity, timing, safety, scope, and response.","dataUri":"/assets/media/c970185a2377ac43.webp"},{"page":65,"id":"poster-065","slug":"urinary-catheter-cauti-safety","title":"Urinary Catheter & CAUTI Safety","arabic":"سلامة القسطرة البولية والوقاية من CAUTI","group":"devices","groupLabel":"Devices & procedures","toolIds":[59],"utilityKeys":["Urinary Catheter & CAUTI Safety Tool"],"canonical":true,"selectionNote":"Upgraded poster selected","asset":"posters/poster-065-urinary-catheter-cauti-safety.webp","questionIds":["Q0581","Q0582","Q0583","Q0584","Q0585","Q0586","Q0587","Q0588","Q0589","Q0590"],"questionCount":10,"meanHyp":71,"domains":["Nursing Fundamentals"],"job":"Decide catheter indication, closed-system/drainage safety, CAUTI prevention, urine-flow troubleshooting and timely removal.","boundary":"Catheter tool owns urinary-device safety. Post-op owns broader postoperative complications; Infection selector owns isolation/transmission precautions.","handoffs":[{"tool":"Post-op Complication & Tubes/Drains Troubleshooter","trigger":"Catheter issue is one part of a broader postoperative complication picture"},{"tool":"Infection Control Selector","trigger":"The question is disease transmission/isolation rather than CAUTI/device prevention"}],"pearl":"Use an indwelling catheter only for valid indications, maintain a closed unobstructed system, and remove it as soon as no longer needed.","trap":"Do not use a catheter for convenience, diagnose CAUTI from cloudy urine alone, or perform fixed-schedule replacement without indication.","dataUri":"/assets/media/6f8ea761aaea5c6e.webp"},{"page":66,"id":"poster-066","slug":"veal-chop-fetal-heart-rate-memory-guide","title":"VEAL-CHOP Fetal Heart Rate Memory Guide","arabic":"دليل VEAL-CHOP لذاكرة نبض الجنين","group":"maternal","groupLabel":"Maternal & pediatrics","toolIds":[35,70],"utilityKeys":["VEAL–CHOP"],"canonical":true,"selectionNote":"Upgraded poster selected","asset":"posters/poster-066-veal-chop-fetal-heart-rate-memory-guide.webp","questionIds":["Q0341","Q0342","Q0343","Q0344","Q0345","Q0346","Q0347","Q0348","Q0349","Q0350","Q0691","Q0692","Q0693","Q0694","Q0695","Q0696","Q0697","Q0698","Q0699","Q0700"],"questionCount":20,"meanHyp":86,"domains":["Maternal-Child Nursing"],"job":"Mnemonic association between fetal heart deceleration types and common causes.","boundary":"VEAL–CHOP is a recognition mnemonic. The Fetal Lab owns interpretation, maternal assessment, interventions, escalation and obstetric emergencies.","handoffs":[{"tool":"Fetal Monitoring & Obstetric Emergency Lab","trigger":"The question asks what to do, severity, or a broader fetal/obstetric pattern"}],"pearl":"VEAL-CHOP recognizes common associations; it does not replace full fetal-monitor interpretation or emergency management.","trap":"Do not use VEAL-CHOP Fetal Heart Rate Memory Guide as a rigid slogan; compare the patient's actual severity, timing, safety, scope, and response.","dataUri":"/assets/media/60a18161894851bd.webp"},{"page":67,"id":"poster-067","slug":"who-5-moments-for-hand-hygiene","title":"WHO 5 Moments for Hand Hygiene","arabic":"لحظات منظمة الصحة العالمية الخمس لنظافة اليدين","group":"safety","groupLabel":"Safety & infection","toolIds":[25],"utilityKeys":["WHO 5 Moments for Hand Hygiene"],"canonical":true,"selectionNote":"Upgraded poster selected","asset":"posters/poster-067-who-5-moments-for-hand-hygiene.webp","questionIds":["Q0241","Q0242","Q0243","Q0244","Q0245","Q0246","Q0247","Q0248","Q0249","Q0250"],"questionCount":10,"meanHyp":73,"domains":["Nursing Fundamentals"],"job":"Choose when hand hygiene is required around patient contact, clean procedures, body-fluid exposure and environment contact.","boundary":"This tool owns timing of hand hygiene, not transmission category or room/PPE selection.","handoffs":[{"tool":"Isolation Precautions","trigger":"Need transmission category/PPE"},{"tool":"Infection Control Selector","trigger":"Disease-specific isolation decision"}],"pearl":"Before patient, before aseptic, after body fluid, after patient, after surroundings.","trap":"Do not use WHO 5 Moments for Hand Hygiene as a rigid slogan; compare the patient's actual severity, timing, safety, scope, and response.","dataUri":"/assets/media/56a6d662b0c15e92.webp"},{"page":68,"id":"poster-068","slug":"wound-pressure-injury-decision-lab","title":"Wound & Pressure Injury Decision Lab","arabic":"مختبر قرار الجروح وإصابات الضغط","group":"devices","groupLabel":"Devices & procedures","toolIds":[57,110],"utilityKeys":["Wound & Pressure Injury Decision Lab"],"canonical":true,"selectionNote":"Upgraded poster selected","asset":"posters/poster-068-wound-pressure-injury-decision-lab.webp","questionIds":["Q0561","Q0562","Q0563","Q0564","Q0565","Q0566","Q0567","Q0568","Q0569","Q0570","Q1091","Q1092","Q1093","Q1094","Q1095","Q1096","Q1097","Q1098","Q1099","Q1100"],"questionCount":20,"meanHyp":87,"domains":["Adult Nursing","Nursing Fundamentals"],"job":"Assess wound/pressure-injury pattern, staging/characteristics, prevention and first nursing response.","boundary":"Wound Lab owns wound/pressure-injury assessment and prevention. Post-op tool owns broader postoperative complications such as dehiscence/evisceration/drains.","handoffs":[{"tool":"Post-op Complication & Tubes/Drains Troubleshooter","trigger":"The wound issue is specifically a postoperative complication within a broader postop case"}],"pearl":"Differentiate pressure injury from other skin damage, individualize prevention, offload pressure, and do not automatically debride stable heel eschar.","trap":"Do not stage all skin damage as pressure injury or automatically debride stable dry heel eschar.","dataUri":"/assets/media/1604f16e51cc8326.webp"}];
  window.SNLE_QUESTIONS=[{"toolNumber":1,"toolQuestionNumber":1,"globalNumber":1,"options":[{"label":"A","text":"A postoperative patient with incisional pain 7/10 thirty minutes after analgesia."},{"label":"B","text":"A patient with COPD whose SpO2 is 91% on prescribed oxygen and unchanged from baseline."},{"label":"C","text":"A patient 2 hours after extubation with new inspiratory stridor and increasing retractions."},{"label":"D","text":"A patient with an NG tube reporting nausea and 150 mL green drainage in 2 hours."}],"id":"Q0001","tool":"T001 ABCDE Priority Framework","stem":"A nurse receives handoff on four patients. Which patient should be assessed first?","key":"C","answerText":"A patient 2 hours after extubation with new inspiratory stridor and increasing retractions.","rationale":"New stridor after extubation suggests an evolving upper-airway obstruction.","pearl":"Treat the earliest unresolved life threat, then reassess from A again.","trap":"Do not use ABCDE Priority Framework as a rigid slogan; compare the patient's actual severity, timing, safety, scope, and response.","toolName":"ABCDE Priority Framework","studyFocus":"Treat the earliest unresolved life threat, then reassess from A again.","domain":"Nursing Fundamentals","subdomain":"Fundamentals of nursing","process":"upper-airway obstruction / stridor","population":"Adult/unspecified","setting":"Inpatient/acute care","construct":"upper-airway obstruction / stridor — priority selection","hyp":90,"hypBand":"HYP5","difficulty":"Hard","judgment":"Prioritize Hypotheses","evidence":"E2 - Established nursing/clinical principle; source-family aligned","quality":"QS1 - Standardized; structurally clean; validation pending","actionRequired":"KEEP - clinical SME validation + pilot psychometrics","misconceptions":{"A":"Priority inversion / lower-acuity focus","B":"Stable-baseline / lower-acuity priority error","C":"KEY - best supported response","D":"Plausible but lower-priority/incomplete response"}},{"toolNumber":1,"toolQuestionNumber":2,"globalNumber":2,"options":[{"label":"A","text":"Complete a detailed pain assessment before changing the respiratory plan."},{"label":"B","text":"Encourage oral fluids and reassess the respiratory rate in 30 minutes."},{"label":"C","text":"Position the patient upright, apply appropriate oxygen, and rapidly reassess breathing and response."},{"label":"D","text":"Obtain a sputum specimen before starting an intervention that may alter respiratory findings."}],"id":"Q0002","tool":"T001 ABCDE Priority Framework","stem":"A patient with pneumonia has SpO2 84%, RR 34/min, and accessory-muscle use. What should the nurse do first?","key":"C","answerText":"Position the patient upright, apply appropriate oxygen, and rapidly reassess breathing and response.","rationale":"The patient has an immediate breathing problem requiring support and reassessment.","pearl":"Treat the earliest unresolved life threat, then reassess from A again.","trap":"Do not use ABCDE Priority Framework as a rigid slogan; compare the patient's actual severity, timing, safety, scope, and response.","toolName":"ABCDE Priority Framework","studyFocus":"Treat the earliest unresolved life threat, then reassess from A again.","domain":"Nursing Fundamentals","subdomain":"Fundamentals of nursing","process":"pneumonia / lower respiratory infection","population":"Adult/unspecified","setting":"Inpatient/acute care","construct":"pneumonia / lower respiratory infection — immediate nursing action","hyp":90,"hypBand":"HYP5","difficulty":"Medium","judgment":"Take Action","evidence":"E2 - Established nursing/clinical principle; source-family aligned","quality":"QS1 - Standardized; structurally clean; validation pending","actionRequired":"KEEP - clinical SME validation + pilot psychometrics","misconceptions":{"A":"Assessment-action sequencing error","B":"Assessment-action sequencing error","C":"KEY - best supported response","D":"Plausible but lower-priority/incomplete response"}},{"toolNumber":1,"toolQuestionNumber":3,"globalNumber":3,"options":[{"label":"A","text":"Call for urgent help, support circulation, obtain rapid vascular access as appropriate, and reassess perfusion."},{"label":"B","text":"Ask the patient to rate abdominal pain before initiating other care."},{"label":"C","text":"Administer the scheduled proton-pump inhibitor and recheck blood pressure in one hour."},{"label":"D","text":"Collect a stool specimen for occult blood before contacting the clinical team."}],"id":"Q0003","tool":"T001 ABCDE Priority Framework","stem":"A patient with an upper GI bleed becomes pale and restless; BP falls to 82/48 mmHg and HR rises to 132/min. What should the nurse do first?","key":"A","answerText":"Call for urgent help, support circulation, obtain rapid vascular access as appropriate, and reassess perfusion.","rationale":"Hypotension, tachycardia, pallor, and restlessness with bleeding indicate circulatory instability.","pearl":"Treat the earliest unresolved life threat, then reassess from A again.","trap":"Do not use ABCDE Priority Framework as a rigid slogan; compare the patient's actual severity, timing, safety, scope, and response.","toolName":"ABCDE Priority Framework","studyFocus":"Treat the earliest unresolved life threat, then reassess from A again.","domain":"Nursing Fundamentals","subdomain":"Fundamentals of nursing","process":"GI bleeding / hemorrhage","population":"Adult/unspecified","setting":"Inpatient/acute care","construct":"GI bleeding / hemorrhage — immediate nursing action","hyp":90,"hypBand":"HYP5","difficulty":"Medium","judgment":"Take Action","evidence":"E2 - Established nursing/clinical principle; source-family aligned","quality":"QS1 - Standardized; structurally clean; validation pending","actionRequired":"KEEP - clinical SME validation + pilot psychometrics","misconceptions":{"A":"KEY - best supported response","B":"Priority inversion / lower-acuity focus","C":"Assessment-action sequencing error","D":"Premature escalation / omission of immediate nursing action"}},{"toolNumber":1,"toolQuestionNumber":4,"globalNumber":4,"options":[{"label":"A","text":"Give a rapid IV fluid bolus despite normal perfusion and no evidence of volume loss."},{"label":"B","text":"Delay assessment because oxygenation and blood pressure remain normal."},{"label":"C","text":"Start chest compressions because reduced responsiveness is sufficient to diagnose cardiac arrest."},{"label":"D","text":"Perform a rapid neurologic assessment, check bedside glucose, and escalate the acute change in consciousness."}],"id":"Q0004","tool":"T001 ABCDE Priority Framework","stem":"A patient suddenly becomes difficult to arouse. Airway is patent, SpO2 96%, RR 16/min, and BP 126/74 mmHg. What should the nurse do next?","key":"D","answerText":"Perform a rapid neurologic assessment, check bedside glucose, and escalate the acute change in consciousness.","rationale":"With airway, breathing, and circulation adequate, the new neurologic change is the next priority.","pearl":"Treat the earliest unresolved life threat, then reassess from A again.","trap":"Do not use ABCDE Priority Framework as a rigid slogan; compare the patient's actual severity, timing, safety, scope, and response.","toolName":"ABCDE Priority Framework","studyFocus":"Treat the earliest unresolved life threat, then reassess from A again.","domain":"Nursing Fundamentals","subdomain":"Fundamentals of nursing","process":"respiratory failure / hypoxemia","population":"Adult/unspecified","setting":"Inpatient/acute care","construct":"respiratory failure / hypoxemia — one-best nursing decision","hyp":90,"hypBand":"HYP5","difficulty":"Hard","judgment":"Take Action","evidence":"E2 - Established nursing/clinical principle; source-family aligned","quality":"QS1 - Standardized; structurally clean; validation pending","actionRequired":"KEEP - clinical SME validation + pilot psychometrics","misconceptions":{"A":"Plausible but lower-priority/incomplete response","B":"Delay / failure-to-act error","C":"Premature diagnostic focus / treatment delay","D":"KEY - best supported response"}},{"toolNumber":1,"toolQuestionNumber":5,"globalNumber":5,"options":[{"label":"A","text":"Open and clear the airway with suction while maintaining appropriate cervical-spine precautions."},{"label":"B","text":"Obtain laboratory specimens before attempting to clear the airway."},{"label":"C","text":"Administer analgesia before performing airway interventions."},{"label":"D","text":"Inspect both legs for deformity before addressing the noisy respirations."}],"id":"Q0005","tool":"T001 ABCDE Priority Framework","stem":"A trauma patient has gurgling respirations and blood in the mouth. Which action is most appropriate?","key":"A","answerText":"Open and clear the airway with suction while maintaining appropriate cervical-spine precautions.","rationale":"Gurgling with oral blood indicates threatened airway patency.","pearl":"Treat the earliest unresolved life threat, then reassess from A again.","trap":"Do not use ABCDE Priority Framework as a rigid slogan; compare the patient's actual severity, timing, safety, scope, and response.","toolName":"ABCDE Priority Framework","studyFocus":"Treat the earliest unresolved life threat, then reassess from A again.","domain":"Nursing Fundamentals","subdomain":"Fundamentals of nursing","process":"upper-airway obstruction / stridor","population":"Adult/unspecified","setting":"Inpatient/acute care","construct":"upper-airway obstruction / stridor — one-best nursing decision","hyp":88,"hypBand":"HYP4","difficulty":"Medium","judgment":"Take Action","evidence":"E2 - Established nursing/clinical principle; source-family aligned","quality":"QS1 - Standardized; structurally clean; validation pending","actionRequired":"KEEP - clinical SME validation + pilot psychometrics","misconceptions":{"A":"KEY - best supported response","B":"Plausible but lower-priority/incomplete response","C":"Plausible but lower-priority/incomplete response","D":"Plausible but lower-priority/incomplete response"}},{"toolNumber":1,"toolQuestionNumber":6,"globalNumber":6,"options":[{"label":"A","text":"Titrate oxygen to the prescribed or clinically appropriate target and reassess work of breathing, mentation, and saturation."},{"label":"B","text":"Withhold oxygen until an arterial blood gas confirms the exact cause."},{"label":"C","text":"Give a rapid crystalloid bolus first because respiratory deterioration implies hypovolemia."},{"label":"D","text":"Set oxygen automatically to achieve 100% saturation regardless of the patient condition."}],"id":"Q0006","tool":"T001 ABCDE Priority Framework","stem":"A patient with chronic hypercapnic respiratory disease deteriorates and requires oxygen. Which approach is most appropriate?","key":"A","answerText":"Titrate oxygen to the prescribed or clinically appropriate target and reassess work of breathing, mentation, and saturation.","rationale":"Oxygen therapy should treat hypoxemia while being individualized and reassessed.","pearl":"Treat the earliest unresolved life threat, then reassess from A again.","trap":"Do not use ABCDE Priority Framework as a rigid slogan; compare the patient's actual severity, timing, safety, scope, and response.","toolName":"ABCDE Priority Framework","studyFocus":"Treat the earliest unresolved life threat, then reassess from A again.","domain":"Nursing Fundamentals","subdomain":"Fundamentals of nursing","process":"respiratory failure / hypoxemia","population":"Adult/unspecified","setting":"Inpatient/acute care","construct":"respiratory failure / hypoxemia — one-best nursing decision","hyp":90,"hypBand":"HYP5","difficulty":"Medium","judgment":"Take Action","evidence":"E2 - Established nursing/clinical principle; source-family aligned","quality":"QS1 - Standardized; structurally clean; validation pending","actionRequired":"KEEP - clinical SME validation + pilot psychometrics","misconceptions":{"A":"KEY - best supported response","B":"Delay / failure-to-act error","C":"Plausible but lower-priority/incomplete response","D":"Premature escalation / omission of immediate nursing action"}},{"toolNumber":1,"toolQuestionNumber":7,"globalNumber":7,"options":[{"label":"A","text":"Reassess airway and breathing before moving on to circulation and neurologic status."},{"label":"B","text":"Focus only on the original abnormal vital sign rather than reassessing the patient."},{"label":"C","text":"Move directly to discharge planning because the immediate symptom was treated."},{"label":"D","text":"Document the intervention and wait for the next routine observation round."}],"id":"Q0007","tool":"T001 ABCDE Priority Framework","stem":"After supporting a postoperative patient with acute dyspnea, what should the nurse do next?","key":"A","answerText":"Reassess airway and breathing before moving on to circulation and neurologic status.","rationale":"After treatment, reassess from the beginning to confirm earlier priorities remain controlled.","pearl":"Treat the earliest unresolved life threat, then reassess from A again.","trap":"Do not use ABCDE Priority Framework as a rigid slogan; compare the patient's actual severity, timing, safety, scope, and response.","toolName":"ABCDE Priority Framework","studyFocus":"Treat the earliest unresolved life threat, then reassess from A again.","domain":"Nursing Fundamentals","subdomain":"Fundamentals of nursing","process":"abcde priority","population":"Adult/unspecified","setting":"Perioperative/postoperative care","construct":"abcde priority — one-best nursing decision","hyp":88,"hypBand":"HYP4","difficulty":"Easy","judgment":"Take Action","evidence":"E2 - Established nursing/clinical principle; source-family aligned","quality":"QS1 - Standardized; structurally clean; validation pending","actionRequired":"KEEP - clinical SME validation + pilot psychometrics","misconceptions":{"A":"KEY - best supported response","B":"Absolutist / overgeneralization error","C":"Routine-task precedence error","D":"Delay / failure-to-act error"}},{"toolNumber":1,"toolQuestionNumber":8,"globalNumber":8,"options":[{"label":"A","text":"The quieter chest indicates bronchodilator therapy has been effective."},{"label":"B","text":"The patient is ready for discharge teaching because wheezing is no longer prominent."},{"label":"C","text":"The reduced breath sounds may reflect worsening airflow obstruction and impending respiratory failure."},{"label":"D","text":"The change is most consistent with anxiety because the respiratory rate is high."}],"id":"Q0008","tool":"T001 ABCDE Priority Framework","stem":"A patient with severe asthma has loud wheezing, then becomes quieter while remaining tachypneic and exhausted. What is the priority interpretation?","key":"C","answerText":"The reduced breath sounds may reflect worsening airflow obstruction and impending respiratory failure.","rationale":"A quiet chest in severe asthma can represent critically reduced airflow rather than improvement.","pearl":"Treat the earliest unresolved life threat, then reassess from A again.","trap":"Do not use ABCDE Priority Framework as a rigid slogan; compare the patient's actual severity, timing, safety, scope, and response.","toolName":"ABCDE Priority Framework","studyFocus":"Treat the earliest unresolved life threat, then reassess from A again.","domain":"Nursing Fundamentals","subdomain":"Fundamentals of nursing","process":"asthma / bronchospasm","population":"Adult/unspecified","setting":"Inpatient/acute care","construct":"asthma / bronchospasm — priority selection","hyp":90,"hypBand":"HYP5","difficulty":"Medium","judgment":"Analyze Cues","evidence":"E2 - Established nursing/clinical principle; source-family aligned","quality":"QS1 - Standardized; structurally clean; validation pending","actionRequired":"KEEP - clinical SME validation + pilot psychometrics","misconceptions":{"A":"Cue misinterpretation / false reassurance","B":"Plausible but lower-priority/incomplete response","C":"KEY - best supported response","D":"Plausible but lower-priority/incomplete response"}},{"toolNumber":1,"toolQuestionNumber":9,"globalNumber":9,"options":[{"label":"A","text":"Poor appetite and generalized weakness for two days."},{"label":"B","text":"BP 78/42 mmHg with cool mottled skin and delayed capillary refill."},{"label":"C","text":"Temperature 39.1 C with chills that began 30 minutes ago."},{"label":"D","text":"WBC 17,000/mm3 reported with morning laboratory results."}],"id":"Q0009","tool":"T001 ABCDE Priority Framework","stem":"A septic patient is febrile and confused. Which finding requires the most immediate response?","key":"B","answerText":"BP 78/42 mmHg with cool mottled skin and delayed capillary refill.","rationale":"Profound hypotension with poor perfusion is an immediate circulation threat.","pearl":"Treat the earliest unresolved life threat, then reassess from A again.","trap":"Do not use ABCDE Priority Framework as a rigid slogan; compare the patient's actual severity, timing, safety, scope, and response.","toolName":"ABCDE Priority Framework","studyFocus":"Treat the earliest unresolved life threat, then reassess from A again.","domain":"Nursing Fundamentals","subdomain":"Fundamentals of nursing","process":"shock / tissue hypoperfusion","population":"Adult/unspecified","setting":"Inpatient/acute care","construct":"shock / tissue hypoperfusion — recognition of clinically significant cues","hyp":74,"hypBand":"HYP3","difficulty":"Medium","judgment":"Prioritize Hypotheses","evidence":"E2 - Established nursing/clinical principle; source-family aligned","quality":"QS2 - Standardized; lower-yield breadth item","actionRequired":"REVIEW/KEEP only if blueprint breadth justifies + SME/pilot","misconceptions":{"A":"Priority inversion / lower-acuity focus","B":"KEY - best supported response","C":"Plausible but lower-priority/incomplete response","D":"Plausible but lower-priority/incomplete response"}},{"toolNumber":1,"toolQuestionNumber":10,"globalNumber":10,"options":[{"label":"A","text":"Apply oxygen, position the patient as indicated by the suspected complication, and activate urgent clinical help."},{"label":"B","text":"Obtain a complete medication history before changing the plan."},{"label":"C","text":"Prepare discharge instructions while waiting for review."},{"label":"D","text":"Send a routine message to the team and reassess at the next vital-sign round."}],"id":"Q0010","tool":"T001 ABCDE Priority Framework","stem":"A patient suddenly becomes dyspneic after central-line removal. Which action should the nurse take first?","key":"A","answerText":"Apply oxygen, position the patient as indicated by the suspected complication, and activate urgent clinical help.","rationale":"Sudden respiratory deterioration requires immediate oxygenation support and escalation while the cause is assessed.","pearl":"Treat the earliest unresolved life threat, then reassess from A again.","trap":"Do not use ABCDE Priority Framework as a rigid slogan; compare the patient's actual severity, timing, safety, scope, and response.","toolName":"ABCDE Priority Framework","studyFocus":"Treat the earliest unresolved life threat, then reassess from A again.","domain":"Nursing Fundamentals","subdomain":"Fundamentals of nursing","process":"respiratory failure / hypoxemia","population":"Adult/unspecified","setting":"Inpatient/acute care","construct":"respiratory failure / hypoxemia — immediate nursing action","hyp":74,"hypBand":"HYP3","difficulty":"Medium","judgment":"Take Action","evidence":"E2 - Established nursing/clinical principle; source-family aligned","quality":"QS2 - Standardized; lower-yield breadth item","actionRequired":"REVIEW/KEEP only if blueprint breadth justifies + SME/pilot","misconceptions":{"A":"KEY - best supported response","B":"Routine-task precedence error","C":"Delay / failure-to-act error","D":"Communication/documentation omission or sequencing error"}}];
